SY_TALK("oatvELWaX9k.hi",[[1,["और आप सबसे मेरी विनती है, कि जो लोग","परमात्मा की खोज में भटक रहे हैं,"]],[11,["उन्हें भी पहले संगीत का आश्रय लेना पड़ेगा -","उसके बगैर काम नहीं बनने वाला।"]],[19,["क्योंकि अपने भारतीय संगीत की विशेषता यह है कि","यह अत्यंत तपस्विता से और मेहनत से ही मिलती है।"]],[28,["उसकी गंभीरता, उसकी उड़ान, उसका फैलाव, उसकी","गहराई, उसकी नज़ाकत, सब चीज़ों में परमात्मा के","दर्शन मनुष्य को हो सकते हैं।"]],[44,["और सारा ही संगीत उस ओम(ॐ) से निकला है,","जिसे लोग रूह के नाम से जानते हैं।"]],[54,["इसलिए, जब इस संगीत से मनुष्य तल्लीन हो जाता","है, उसके लिए आसान है कि वो परमात्मा को पाए।"]],[64,["शायद आपको मेरी बात कुछ काव्यमय लगे","और कुछ यथार्थ से दूर प्रतीत हो,"]],[72,["शायद ऐसा अहसास हो कि मैं कोई बात को इस तरह","से कह रही हूँ, जैसे कि संगीत कलाकारों को आनंद","आये, किन्तु यह बात सच नहीं है।"]],[89,["अपने अंदर भी सात चक्र हैं और सब मिला","कर के बारह चक्र हैं, उसी प्रकार"]],[100,["संगीत में भी सात स्वर और पांच और स्वर मिला","कर के पूरा एक स्केल बन जाता है।"]],[111,["हमारे चक्रों में जब कुण्डलिनी गति करती है, और जो","स्वर उठाती है, वही स्वर हमारे संगीत में माने गए हैं।"]],[122,["हमारा भारतीय संगीत बड़े दृष्टों ने,","ऋषियों ने, मुनियों ने पाया हुआ है।"]],[128,["वह चाहे किसी भी धर्म के रहे हों, वह किसी भी देश के","हिस्से में पैदा हुए हों, उत्तर, दक्षिण, पूर्व, पश्चिम वह","कहीं भी उनका जन्म हुआ हो,"]],[141,["लेकिन उन्होंने आत्मा को नींव समझ करके ही","सारी संगीत की इमारत बाँधी हुई है।"]],[149,["हवा में चीज़ उड़ने नहीं दी जैसे वेस्टर्न म्यूजिक का है।","वेस्टर्न म्यूजिक तो कटी पतंग की तरह बहती रहती है,"]],[156,["कभी ठंडी हो जाएगी, कभी गरम हो जाएगी,","कभी कहीं बहेगी, कहीं कहीं बहेगी।"]],[162,["लेकिन हमारा भारतीय संगीत एक चीज़ से हमेशा","बँधा रहता है, और वो चीज़ है, हमारी आत्मा।"]],[171,["अब आजकल मैं देखती हूँ कि लोग-बाग इस","संगीत को पसंद नहीं करते ख़ास, न ही उसके","समझने की इच्छा रखते हैं।"]],[180,["उसकी वजह यह है कि हम लोगों के लिए कोई नई","चीज़ आ गई है जो दीखने में आसान नज़र आती है।"]],[187,["लेकिन आत्मा को पाना भी तो मनुष्य भूल गया है।","आत्मा की बात करना भी पुरानी हो गई और","आजकल फैशन में नहीं है।"]],[197,["आजकल अगर कोई आत्मा की बात करता है,","तो लोग सोचते हैं कि माताजी भी क्या पुराने","ज़माने की बात ले बैठे,"]],[203,["ये आत्मा-वात्मा कोई चीज़ है या नहीं और","परमात्मा भी नाम की कोई चीज़ है या नहीं।"]],[209,["लेकिन अब भी इस भारतवर्ष में कितने भी लोग","परमात्मा की ओर से मुँह मोड़ चुके हों तो भी,","उनकी डोर तो उन्हीं के हाथ में है,"]],[224,["और कितना भी आप दूर चले जाएँ, इस भारतवर्ष की","ज़मीन ऐसी है, कि आप भगवान को भूल नहीं सकते।"]],[235,["ऊपरी तरह से आप कुछ भी कहते रहें, कि","परमात्मा नहीं है, उनकी कोई शक्ति नहीं है,","और हम उनको मानते नहीं,"]],[244,["और हम तो अपनी ही शक्ति को मानते हैं, लेकिन","अभी तक मैंने ऐसा कोई भारतीय देखा नहीं,"]],[252,["कि जो एक हद्द पर पहुँच कर कहता है कि,","\"भई होना चाहिए भगवान नाम की चीज़।\""]],[258,["और हम कहते हैं कि चीज़ ही नहीं है, भगवान","तो सर्वव्यापी शक्ति हैं।"]],[270,["और उस शक्ति को पाने के लिए, उस शक्ति","को जानने के लिए, हम लालायित नहीं होते।"]],[277,["न ही हमें उसके लिए कुतूहूल होता है और न हम","समझते हैं कि ऐसी कोई शक्ति है जो हमारे अंदर से","प्रवाहित हो जाती है।"]],[285,["वजह ये है कि इसपर बहुत ही कम लिखा गया और","जो भी कहा गया है, बहुत गुप्त रूप से कहा गया है।"]],[293,["जिस चीज़ को हम इस देश की सम्पदा या","संपत्ति या बड़ी भारी जिसे परंपरा समझते हैं,"]],[300,["उस परम्पराओं में भी, इस चीज़ के बारे में कहा","तो गया है लेकिन यह चीज़ घटित कैसी होती है,","इस पर बहुत ही कम प्रकाश पड़ा है।"]],[311,["उसकी वजह ये है कि जब इसका समय","आएगा तभी ये बात उद्घाटित होगी।"]],[319,["ये सोच करके और ये समझ करके ही लोगों","ने इस बात को गुप्त रखा।"]],[328,["सबने कहा है कि परमात्मा की सर्वव्यापी","शक्ति इस संसार में विचरण करती है।"]],[335,["और हम भी रोज़मर्रा देखते हैं कि जितनी जीवित","व्यवस्थाएँ हैं, जितना भी जीवित कार्य है,"]],[342,["वो एक शक्ति कोई न कोई करती है और वो शक्ति","एक फ़ूल में से फल निकाल देती है, एक बीज","में से वृक्ष निकाल देती है।"]],[357,["सारे जितने जीवन्त कार्य हैं, वो शक्ति करती है","और वो शक्ति जो भी है, उसे हम जानते नहीं हैं,"]],[364,["और उसे हम पा नहीं पाते। ये कार्य हम कर","नहीं सकते और ये हमसे ऊँची चीज़ है।"]],[371,["इसको पाने के लिए अगर मनुष्य ने एक चीज़ ऐसी","तय कर ली कि, \"साब ये चीज़ कोई है ही नहीं,\" तब","तो फिर ऐसे इंसानों से बात करना ही व्यर्थ है।"]],[385,["क्योंकि अँधेरे में बैठे हुए लोग अगर कहें, कि","सूरज नाम की कोई चीज़ है ही नहीं, तो फिर","वो आगे बढ़ेंगे कैसे ?"]],[393,["लेकिन दूसरे लोग ज़रूर ऐसे हो सकते हैं, कि वो","सोचते हैं कि, \"अच्छा, इन सब लोगों ने कहा है कि,"]],[401,["सूरज नाम की कोई चीज़ है, तो उसे देखा क्यों","नहीं जाए, उसे जाना क्यों न जाए ?\""]],[407,["और सबने क्या कहा है, किस तरह से जाना","जाता है ? किसी ने ऐसा नहीं कहा है कि,"]],[413,["आप सर के बल खड़े हो जाइये, तो आपको परमात्मा","मिल जायेगा या नाक में रस्सी डाल के खींचिए ,","तो आपको परमात्मा मिल जायेगा।"]],[421,["इस तरह की विक्षिप्त क्रियाएँ करने से परमात्मा","मिलता है, ऐसे किसी ने नहीं कहा। ये तो कोई","नई-नई चीज़ रोज़ निकलती रहती है।"]],[433,["सब अपने शरीर को पाने की, ज़मीन-जुमला और","दुनिया भर की बेकार की चीज़ें जोड़ने की","व्यवस्था में लगे रहते हैं।"]],[445,["लेकिन जिसको जुटाना है, उधर हमारी दृष्टि","इसलिए नहीं है, कि कोई ऐसा मिलता भी तो","नहीं जिसने जुटाया है।"]],[453,["जो भी बात करता है, मुझे ही पता होता है, किसी जेल","से छूटा हुआ फरारी या कोई पैसा कमाने वाला यहाँ","आदमी पहुँचा हुआ है।"]],[463,["बात तो परमात्मा की करता है और घर में ठगी","करता है इसलिए भी परमात्मा से विश्वास टूटना,","बिलकुल सही बात है, बिलकुल सही बात है।"]],[476,["लेकिन इसमें परमात्मा का क्या दोष है? परमात्मा","ने तो आपको एक अमीबा से इंसान बना दिया है।"]],[488,["उसने आपको ये सुन्दर सृष्टि रच दी है। ये सारे रंग","और ये स्वर और यह और सारा मधुर संगीत,","परमात्मा ही के चरणों से आया है।"]],[499,["उसने ही इसका आनंद उठाने की शक्ति दी हमारे","अंदर। इसने ही हमें अपने माँ-बाप, बच्चे सबको","पहचानने की, उनको प्रेम करने की भी शक्ति दी है।"]],[511,["उसी ने हमारे खाने-पीने की और हर","चीज़ की व्यवस्था कर रखी है"]],[515,["लेकिन अगर हमीं अपने आपस में लड़-झगड़ करके,","सिर फुटौअल करते हैं, उसे परमात्मा क्या करे?"]],[525,["ये सब मनुष्य की बनाईं समस्याएँ हैं।","परमात्मा ने हमारे लिए कोई समस्या नहीं","बनाई, कोई सी भी नहीं।"]],[533,["पर, एक बार माँगने की बात है और आप जान सकते हैं","कि वह परमात्मा क्या है और आपका आत्मा क्या है?"]],[542,["इतने सुन्दर तरीके से अपने अंदर उन्होंने पूरा यन्त्र","बिठाया हुआ है।"]],[549,["धीरे-धीरे, जैसे-जैसे हम लोग उत्क्रांति कर चुके,","एवोल्यूशन होते रहा"]],[556,["वैसे-वैसे, धीरे-धीरे, हमारे अंदर यह सब संस्थाएँ","एक के बाद एक जुटती गई। और ये सब चक्रों","द्वारा हमारे अंदर प्रस्थापित।"]],[571,["बड़ी मेहनत से ये यंत्र को बनाया गया,","बड़े संजो कर इसे बनाया गया,"]],[576,["कि अंतिम लक्ष्य ये है, कि जो बाह्य में","मनुष्य दिखाई देता है, वह महा-मानव हो जाए।"]],[584,["जो सर्व-साधारण और तुच्छ और हीन माना","जाता है, वो अत्यंत उच्च कोटि का साधन","परमात्मा का बन जाए।"]],[592,["लेकिन मनुष्य का स्वभाव ऐसा है कि, वो सब","चीज़ को अपना साधन बनाना चाहता है,किसी","का साधन नहीं बनना चाहता।"]],[600,["उसके स्वभाव से विपरीत है। किसी का साधन वो क्यों","बने? पर जिसने आपको साधन स्वरुप बनाया है,","उसके तो आपको साधन बनना ही पड़ेगा?"]],[614,["अगर आप उसका भी साधन बनने के लिए तैयार","नहीं हैं, तो आपने जितने साधन जुटायें हैं,","ये सब व्यर्थ हैं।"]],[621,["इनसे आपको कोई सुख की प्राप्ति और","आनंद की प्राप्ति नहीं हुई, न होगी।"]],[626,["आप उन देशों में जा कर देखिये जहाँ","उन लोगों ने हज़ारों साधन जुटा लिए हैं।"]],[632,["पच्चीसों तरह के साधन जुटा लिए हैं। आप","अगर जाइए तो एक ऐसी मोटरें हैं,"]],[637,["कि बैठे-बैठे आप उसको दरवाज़ा खोल लीजिए,","उसका कमरा बना लीजिए, उसका ये कर लीजिए -","इसमें रखा क्या है?"]],[645,["इस सब तमाशे-बाजी में रखा क्या है? ऐसे-ऐसे","मकान आप हैं, कि जहाँ आप जाइए,"]],[651,["तो आपको वहाँ पर एक ही जगह में","स्विमिंग-पूल भी मिल जाएगा,"]],[655,["और एक ही जगह में आपको बैठे-बैठे, आप अपने","मोटर भी चलवा लें, सब करवा लें - तो फायदा क्या है?"]],[664,["ये सब तमाशे-बाजी करके इन्सान को मिला क्या?","इससे किसी को आनंद की उपलब्धि हुई ?"]],[670,["आनंद की बात छोड़िये, मैं तो यहाँ तक कहतीं हूँ,","कि किसी के अंदर किसी भी प्रकार की सुज्ञता आई है?"]],[680,["और सुज्ञता की भी बात न करें,","तो किसी के अंदर शान्ति है?"]],[686,["जब युद्ध नहीं होता, तो युद्ध की तैयारियाँ होतीं हैं और","फिर उसके बाद, युद्ध होने के बाद, फिर युद्ध की","तैयारियाँ।"]],[694,["यह तो मनुष्य की सुज्ञता हो गयी हुई है इन","देशों में, और शान्ति की बात ये है कि,"]],[702,["दो इंसान झगड़ा किए बगैर, इन देशों में,","पाँच मिनट से ज़्यादा नहीं रह सकते।"]],[710,["ऐसी दशा में ये सोचना चाहिए, कि जितना कुछ","हमारे लिए बहुमूल्य है, जिसकी हमें चाहत है,"]],[722,["वो छोटी-छोटी चीज़ें तक वहाँ नहीं मिल सकतीं, जैसे","कि, एक माँ का प्यार, एक बाप का आश्रय, एक बच्चों","का दुलार और उनकी आज्ञाकारिता - कुछ भी नहीं।"]],[741,["आप सब चीज़ों से अछूते, इन पैसों से बनाई","हुई, चमकती हुई, कृत्रिम दुनिया में, झूठी दुनिया","में रह रहें हैं।"]],[759,["इससे परे परमात्मा की सच्ची दुनिया है, उसका","सच्चा राज है, उसकी सच्ची मोहब्बत है।"]],[770,["उसको आपने अभी तक जाना ही नहीं है, उसको","आपने देखा ही नहीं है, इसलिए इन सब चीज़ों को","आप बहुत ऊँची चीज़ समझते हैं।"]],[783,["लेकिन ये चीज़ें किसी भी प्रकार आपको सुख नहीं दे","सकतीं। अभी देखिये, आप यहाँ संगीत सुन रहे थे -"]],[792,["जिन्होंने बजाया दूसरों को आनंद देने के","लिए, वो सुखदायी चीज़ होगी।"]],[798,["लेकिन अगर आप आज इस कारपेट के धनी हैं,","तो आपके लिए सरदर्द की चीज़ हो जाती है।"]],[806,["आप सोचते हैं, कि ख़राब न हो जाए, कहीं","बिगड़ न जाए माताजी इस तरह से बैठीं हैं,","कहीं इसके रेशे न टूट जाएँ,"]],[815,["न जाने कितने रूपये का आया। हाय-तोबा लगी","रहेगी कि भई ये चीज़ ली इसको अब कैसे बिछाएँ।"]],[824,["अगर आपने इस चीज़ की परवाह नहीं की तो","दूसरी चीज़ चल पड़ेगी कि और क्या चीज़ लाएं?"]],[830,["ये पड़ोसियों के यहाँ ये चीज़ है,","ये हमारे यहाँ कब आएगी ?"]],[834,["इस उलझन में, और इसी उधेड़ बुन में,","सारी ज़िन्दगी बीत जाएगी। अंत में पता हुआ,"]],[840,["कि जनाबे-अली स्वर्ग सिधार गए और","नहीं तो पागलख़ाने में दाखिल हो गए।"]],[851,["इस हालात को देखते हुए इंसान को सोचना","चाहिए कि भई क्या हम इसलिए पैदा हुए हैं,"]],[858,["क्या परमात्मा ने हमको इंसान इसलिए बनाया,","कि हम पागल-ख़ाने चले जाएँ,"]],[865,["और आपस में लड़ते झगड़ते रहें, क्रोध करते","रहें, किसी भी चीज़ का मज़ा न उठायें,"]],[874,["इंसान का मज़ा न उठायें -","आखिर हो क्या गया है?"]],[881,["हम लोगों में कौन सी चीज़ ऐसी बच गई है,","रह गई है, जो अछूती है, जिसके कारण हम"]],[888,["इस तरह से हो गए हैं, कि हमें अपने से परे","दुनिया दिखाई ही नहीं देती है ?"]],[893,["इतना स्वार्थ, इतनी अंधता, इतना अत्याचार क्यों","आ गया? कभी तो इंसान को एक तरफ बैठ के","ये भी सोचना चाहिए।"]],[904,["हर समय वो यही सोचते रहता है, कि मेरे साथ क्या","ज़्यादती हुई, उन्होंने मेरा कितना घाटा किया,","उन्होंने मुझे कितनी तकलीफ़ दी।"]],[912,["और आपने क्या किया है? फिर ये भी सोचने लग","जाए, कि मैंने कितनी तकलीफ़ दी है, तो भी वो सोच","हो गया और ये भी एक सोच हो गया।"]],[921,["दोनों तरह से आदमी शोक में ही डूबा हुआ है।"]],[926,["तो क्या परमात्मा ने आपको इसलिए इंसान बनाया,","कि आप बैठ करके हर समय यहाँ पर रोया करें","और शोक मनाया करें?"]],[938,["क्या यही परमात्मा की इच्छा थी, कि ऐसे","शोकग्रस्त, पीड़ित, दुखी, रोगी, ऐसे लोग बनायें ?"]],[948,["या इस तरह के लोग, जो अपने अहंकार में डूबे","हुए हैं, जो चाहें सो करें? महा बेवक़ूफ़।"]],[957,["एक साहब एक दिन आये और उलटे कोट-वोट","पहन के। मैंने कहा कि, \"साहब, उल्टा कोट","क्यों पहन लिया?\""]],[965,["कहने लगे, \"इसमें क्या ख़राबी साहब, आप क्यों","कहते?\" मैंने कहा, \"ख़राबी नहीं है लेकिन सीधा","दिखने में अच्छा लगता है, क्या हर्ज़ है?\""]],[973,["\"तो आपने क्या समझ रखा है? हम चाहे जो","करें, आप कौन होतीं हैं कहने वाली?\""]],[976,["मैंने कहा, \"ठीक है। बात ये है आँख में दिखाई","देता है इसलिए कह दिया, आगे नहीं कहेंगे।\""]],[980,["पता हुआ कि ये बहुत रईस आदमी हैं। तो रईस आदमी","ये सोचता है कि वो जो चाहे सो करे। क्योंकि ये बहुत","रईस है, ये सोचते हैं, चाहे जो समझ लें।"]],[992,["दूसरे जो अपने को गरीब कहते हैं,","उनका हाल और अच्छा है।"]],[996,["अब आजकल निकला है, गरीबों की मदद","करो, गरीबों की मदद करो।'"]],[1000,["भई मुझे तो गरीब दिखाई नहीं देते, क्योंकि","किसी को सौ रुपया दे दीजिए, तो वह सीधे जाता","है, कहाँ, तो शराब के दुकान पे।"]],[1012,["ये अगर आदमी गरीब होता, तो ये सौ रुपया ले","के शराब की दुकान पे क्यों तशरीफ़ ले जा रहा?"]],[1020,["इसको तो चाहिए, कि घर जाए अपने बाल-बच्चों","को खाना पीना दे। लेकिन ये चले सीधे शराबखाने।"]],[1029,["इसका मतलब ये क्या गरीब हैं? 'स्ट्राइक करो,","स्ट्राइक करो, भत्ता बढ़ाना चाहिए, बड़ी मँहगाई","हो गई, बड़ी मँहगाई हो गई।'"]],[1038,["अच्छा भई भत्ता बढ़ गया। जा कहाँ","रहे हैं ? वही शराबखाने।"]],[1044,["पूछा, \"भई तुमने भत्ता क्यों बढ़वाया?\" \"माताजी","आपको पता है, शराब की बोतल की कीमत","बहुत बढ़ गई है।\""]],[1050,["आपको तो पता नहीं, आप पीते नहीं, आपको क्या","मालूम? \"ठीक है भैया, हम तो अज्ञानी हैं।\""]],[1058,["सो ऐसे गरीबों से भी क्या किया जाए? और गरीबों","में एक अहंकार है कि, 'हम गरीब हैं।' ये भी एक","अहंकार होता है गरीबों में।"]],[1068,["जैसे भिखारी है, आएगा, \"आप साहब दो रुपया","दे दीजिए।\" \"भैया, दो नहीं एक है, एक ले लो।\""]],[1074,["\"अरे, क्या समझते हैं आपको, अपने लिए","रखिये, पान बीड़ी खाइएगा।\""]],[1078,["इस तरह से अहंकारी, आपको सब आजकल गरीबों ने","भी अपना एक स्थान बना लिया कि, 'हम गरीब हैं।'"]],[1085,["अच्छे साब गरीब हैं ! गरीबी की नम्रता तो कहीं दिखाई","नहीं देती, उलटे इस कदर खोपड़ी पर चढ़े हुए हैं कि,"]],[1092,["ये गरीब कैसे और ये रईस कैसे,","कुछ समझ में नहीं आ रहा ?"]],[1098,["न बाप-बेटे का सहूर रहा, न माँ-बहन का ख्याल","रहा। देखने में ये बातें आप लोगों को लगतीं है,"]],[1106,["कि माँ बहुत पुरानी बातें कह रहीं हैं, लेकिन जो कुछ","अपना पुराना था, वो बहुत ज़रूरी था आज के लिए।"]],[1113,["बहुत ज़रूरी है। एक बार फिर मुड़ करके आप सोच","लीजिये। जो कुछ हमने खो दिया है, वो आज मैं","खोज रहीं हूँ आपके अंदर।"]],[1125,["बगैर उसके ये कार्य हो नहीं सकता। जो लोग","अपने को अहंकार में, बहुत बड़ा आदमी समझ रहे हैं,","उनके लिए सहज योग नहीं है,"]],[1135,["और जो गरीब होकर के ये सोच रहे हैं, कि वह","गरीब होकर सबकी खोपड़ी पे लद सकते हैं,","उनके लिए भी सहज योग नहीं है।"]],[1141,["सहज योग उनके लिए है जो समझदार, गहरे,","गंभीर और धार्मिक लोग हैं।"]],[1152,["धर्म का मतलब ये नहीं कि, आप सुबह से शाम","तक माला जपिए, लेकिन धार्मिक का मतलब ये है","कि, जो अपने अंदर एक संतुलन से रहते हैं।"]],[1163,["कोई अतिक्रमण नहीं करे। जितने भी लोग अपने","को फैनेटिक समझते हैं, वो तो काम से गए ही,","उनसे हमारा मतलब नहीं।"]],[1176,["अब ये सोचना चाहिए कि, हम लोगों की आदत","जो पड़ गई है, हमेशा जब भी ऑडियंस होगा,"]],[1184,["तो जो वक्ता होगा वो यही सोचेगा कि भई ये","ऑडियंस को मुझे जीतना है क्योंकि","इनको मुझे वोट देना है।"]],[1191,["वोट नहीं देना हो तो कुछ न कुछ रुपया जमा","करना होगा - कोई न कोई मतलब से ही","ऑडियंस इकठ्ठा होता है, बेमतलब नहीं।"]],[1202,["ऑडियंस से, जो वक्ता होता है, उसे कोई न कोई","मतलब होता है, तभी ऑडियंस इकठ्ठा होता है,"]],[1208,["लेकिन जब संगीत होता है, तब वो ऑडियंस इकट्ठा","होता है, जो चाहता है कि आनंद को उठाये।"]],[1219,["जब कोई कला का कारी होता है, तो वह","ऑडियंस इकठ्ठा होता है, जब सोचता है कि","भई कलाकार का महत्व ज़्यादा है हमसे।"]],[1230,["ऐसी दशा में थोड़ा आगे जाकर आप सोचिए, कि जब","आप कुण्डलिनी के जागरण के लिए यहाँ आये हैं,"]],[1237,["तो समझ लीजिये, कि आप लोग अपने","फायदे के लिए आये हैं, मेरे नहीं।"]],[1246,["आपको अपना फायदा कर लेना है। कुण्डलिनी","की गंगा आप ही के अंदर है।"]],[1253,["वह जागृत भी हो सकती है और आप पार भी हो","सकते हैं, इसमें कोई नवीन बात अब नहीं रह गई"]],[1261,["क्योंकि समां आ गया है। ऐसे विक्षिप्त समय में,","ऐसे भयानक समय में अगर ये कार्य नहीं होगा,","तो कब होगा।"]],[1271,["यही समय है जब कि यह कार्य होना था और होने वाला","है और इस वक़्त आदमी जो है, बहुत बड़े भ्रान्ति में,","बहुत बड़े कन्फूशन में फँसा हुआ है।"]],[1284,["इस वक़्त वो यह नहीं समझ पा रहा सही कौन है और","ग़लत कौन है। लेकिन एक बात आप जान लीजिए कि"]],[1293,["जब मुझे आपसे कुछ लेना ही नहीं है, तब आपको","मुझे देखना है कि, आपमें से सही कौन है,","और ग़लत कौन है।"]],[1303,["आपको यह नहीं देखना कि मैं सही हूँ या ग़लत हूँ","क्योंकि मुझे तो कुछ लेना देना है नहीं आपसे।"]],[1310,["इस बात को पहले समझ लेना चाहिए, क्योंकि","अधिकतर, हम यह देखने आते हैं कि यह सही हैं","या ग़लत हैं।"]],[1318,["लेकिन इस वक़्त थोड़ी नज़र अपनी और होनी चाहिए,","कि क्या हम सही हैं? जिस चीज़ के लिए आये हैं","यह कितनी बड़ी चीज़ है!"]],[1328,["आत्मा का साक्षात्कार, जो सबसे महान चीज़ है।","इससे बढ़कर संसार में पाने के लिए कोई चीज़ ही नहीं"]],[1335,["और अगर वह चीज़ माताजी देने के लिए बैठीं","हुईं हैं, तो क्या वाकई हम इस योग्य हैं?"]],[1342,["मैं कहतीं हूँ हैं, और बिलकुल हैं। अपने","प्रति आस्था रखें और ये कार्य हो सकता है।"]],[1351,["परमात्मा ने बहुत सोच समझ कर के आपको बनाया","है। ऐसा बनाया है कि मैंने इंसान को देखा है,"]],[1358,["वो कितना भी गिरा हुआ हो, कितना भी दुष्कर","हो, उसकी कुण्डलिनी जगा सकते हैं।"]],[1364,["पता नहीं कैसे ! ऐसी कमाल हो गई है परमात्मा की,","इसकी मेहर ऐसी कमाल है, आपसे बतातीं हूँ,"]],[1371,["कि जिसके लिए लोग आ के बताते हैं कि, माताजी ये","तो इतना गया बीता आदमी है, इसको छोड़ दीजिए","आप, वह तक पार हो जाता है।"]],[1379,["क्या कमाल है! मेरे ख्याल से, परमात्मा ने यही","सोचा होगा कि इस वक़्त नहीं इनको पार कराएँगे,"]],[1387,["तो ये गए सब लोग काम से और मैंने जो इतनी","बढ़िया चीज़ बना के रखी है, मेरी जो इतनी","उत्तम कृति मनुष्य है ,"]],[1396,["वो सर्वनाश होने से, मेरी सारी सृष्टि ही ख़तम हो","जाएगी। और इसीलिए यह कार्य बड़े ज़ोरों में हो रहा है।"]],[1404,["लेकिन इंसान ख़ोजता क्या है और जानना क्या","चाहता है, यह वह अपनी बुद्धि से ठहराता है।"]],[1414,["जिस चीज़ को आपने बुद्धि से ठहरा लिया है, वह सब","सीमित बात है, आपकी अपनी बनाई हुई बात है।"]],[1423,["लेकिन जो सच है, जो यथार्थ है, उस असलियत","को पाने के लिए, पहले यह सोचना चाहिए कि","हम उसे जानें, देखें, परखें,"]],[1442,["क्योंकि असलियत अपनी जगह मुक्कमिल है।","उसको आप हासिल नहीं कर सकते जब तक आप","उसको न माने कि वह अपनी जगह है।"]],[1454,["वह ठहरी हुई है अपनी जगह और उस चीज़ को","पाने के लिए आपको वहाँ तक पहुँचना होगा"]],[1460,["न कि वो चीज़ आपके पैरों पे गिरेगी कि,","'साहब, मुझे आप अपने सर उठा लीजिए।'"]],[1468,["मैं माँ हूँ और माँ बच्चों को कभी-कभी सुझाव","देती है और समझाती है और कभी-कभी,","कभी-कभी डाँटना भी पड़ता है।"]],[1481,["बच्चे नासमझ हैं। उनको बहुत प्रेम और बुद्धिमत्ता से","परमात्मा की ओर ले जाना है क्योंकि उसके सिवाय","और कोई चारा मुझे दिखाई नहीं देता है।"]],[1495,["उसको पाए बगैर इंसान तहस-नहस हो जाएगा।","आत्मा को पाए बगैर, आप चाहे कुछ कर लीजिए,"]],[1503,["आप अपने को दूर हटा के रखिए, कुछ भी","कर लीजिए, आप ख़त्म हो जाएँगे।"]],[1509,["परदेसी देशों में जहाँ-जहाँ आप जा के देखिएगा,","आपको आश्चर्य होगा, कि किस रफ़्तार से ये लोग","जहन्नुम में जा रहे हैं, दोज़ख़ में जा रहे हैं,"]],[1528,["कि ज़िन्दगी कहाँ खत्म हो रही है इनका हाल क्या है,","क्योंकि इन्होंने अपनी आत्मा को नहीं पाया है।"]],[1537,["एक पेड़ बाहर से दिखाई देता है, उसको ही","सब कुछ मान लेने से नहीं होता है - उसकी","जो जड़ें हैं, उसको ख़ोजना होगा।"]],[1545,["जब तक उसके जड़ में आप नहीं उतरेंगे, तब तक इस","पेड़ का कोई माना नहीं होता है और वो जड़ हमारे अंदर","है, ख़ासकर इस योग भूमि में है।"]],[1557,["आप चाहे सूट पहन लीजिए, चाहे आप टाई लगा","लीजिए और अपने नाम-धाम भी बदल लीजिए -"]],[1563,["आखिर इस देश के आप बच्चे हैं,","और ये देश एक योगभूमि है।"]],[1571,["इस देश के अंदर ऐसी शक्ति है, कि इस देश के","रहने वालों पे एक विशेष तरह का अधिकार है,","कि वह परमात्मा को प्राप्त करें -"]],[1584,["आप विश्वास नहीं करेंगे। लेकिन जब तक आपके","अंदर प्रकाश नहीं आता, मेरी बातें आपको शायद सच","न लगें, और शायद अच्छी भी न लगें।"]],[1597,["लेकिन जो भी है, यह समझ लेना चाहिए कि","आप में एक विशेष रूप से अधिकार है,","कि आप परमात्मा को पा लें।"]],[1606,["यह आपकी धरोहर है, ये आपका हेरिटेज है, ये","आपको दिया हुआ वर है परमात्मा का, कि आप","इस महान शक्ति को अपने अंदर पा लें।"]],[1620,["इस प्रेम की महान शक्ति को आप पाकर फिर खो","ज़रूर जल्दी देते हैं, जैसे हम लोग भी स्वतंत्रता को","पाकर अब खोने पर आमादा हैं।"]],[1636,["लेकिन यह बहुत आसानी से एक हिंदुस्तानी के","हाथ लग सकती है। इतना आसान नहीं है कि","परदेस में यह काम हो सके।"]],[1645,["लेकिन मैं परदेस काफी घूमती हूँ। वजह ये, कि वहाँ","का एक आदमी अगर पार हो जाए, तो वह एक पेड़","बन के खड़ा हो जाता है"]],[1655,["और हिंदुस्तान में हज़ारों बीजों को अंकुरित करिए,","उसमें कहीं एक-आद होता है जो पेड़ बनता है।"]],[1664,["अपने बारे में हमें प्रतिष्ठा नहीं है। हम अपने","को आँकते नहीं, अपने को समझते नहीं,","हम अपने को जानते नहीं।"]],[1673,["छोटी-छोटी चीज़ों में हमने अपना जीवन व्यर्थ","कर रखा है। कोई भी जीवन में, हमारे लक्ष्य में,","यह नज़र नहीं आता है"]],[1684,["कि उसमें कोई महान, कोई उदात्त, कोई ऊँची,","कोई बढ़िया चीज़ हमने सोची हुई है।"]],[1692,["आज समय आ गया है कि इंसान को सोचना पड़ेगा","और नहीं सोचिएगा तो आगे का हाल बहुत बुरा है।"]],[1704,["अभी जो बिगड़ा है, वो भी सुधर सकता है, वो भी","ठीक हो सकता है, इसलिए सब से पहले,","आत्मा को आप प्राप्त करें।"]],[1715,["अब कैसे प्राप्त करें? सब लोग कहेंगे, \"माँ कैसे?\"","उसकी आपको चिंता करने की ज़रुरत नहीं।"]],[1720,["आपके अंदर ये शक्ति निहित है, आपके अंदर","आत्मा निहित है। जैसे ही ये शक्ति उस आत्मा से","सम्बंधित हो जाती है,"]],[1727,["ये चारों तरफ छाई हुई, ये परमात्मा की परमेश्वरी","शक्ति आपके अंदर महसूस होने लग जाती है।"]],[1736,["एक बीज होता है, उसे आप किस तरह से पनपाते हैं?","बस उसको आप माँ के उदर में छोड़ दें, और","वह अपने आप,"]],[1746,["अपने आप सहज - सहज माने, 'सह' माने साथ","और 'ज' माने पैदा हुआ - आप ही के साथ पैदा हुआ है"]],[1755,["ये अधिकार, कि आपका योग, आपका मिलाप,","उस परमात्मा की शक्ति से हो जायेगा।"]],[1763,["और जैसे कि योग घटित होता है, उसमें पहली मर्तबा,","आपके हाथ वह शक्ति मिल जाती है, जो सर्वव्यापी है।"]],[1776,["उसको आप जानने लग जाते हैं, समझने लग जाते हैं।","धीरे-धीरे ये शक्ति बढ़ती है, और आप इसका काम","समझते हैं, कि किस तरह से चलती है,"]],[1788,["इसको किस तरह से इस्तेमाल करना चाहिए","और जैसे जैसे आप बढ़ते है, ऐसे-ऐसे एक बीज का","एक वृक्ष खड़ा हो सकता है।"]],[1799,["इस विभाग का विशेष कारण ऐसा है, कि न जाने","कैसे हमें यहाँ पर एक आश्रम की जगह मिल गई।"]],[1810,["पहले भी हमें गवर्नमेंट ने जगह दी हुई है, लेकिन","ऐसी दी हुई है, कि कुछ समझ में नहीं आता।"]],[1818,["सब्ज़ी मंडी में जगह दी, जहाँ पर कि बैल बैठे रहते हैं","और वहाँ पर गाड़ियाँ छोड़ी हुईं हैं। पता नहीं गवर्नमेंट","का दिमाग कैसा है?"]],[1827,["हमने कहा, \"भई हम तो यहाँ मैडिटेशन करने वाले","हैं, तो ये कौन सी आपने जगह हमारे लिए","ख़ास ढूँढ कर दी है?\""]],[1836,["इस प्रकार उन्होंने हमें बड़ी बढ़िया जगह दी थी।","बहरहाल, अभी कोशिश कर रहे हैं वह कि","और कोई बढ़िया जगह ढूँढें।"]],[1843,["भगवान जाने अब और कहाँ पहुँचा देंगे। गवर्नमेंट","की बुद्धि जैसे चलेगी वैसे ही चलेगी, अब हम तो","कुछ कर नहीं सकते।"]],[1850,["बहरहाल, परमात्मा की कृपा से ही, यह जगह","हमें यहाँ मिल गई - छोटी सी जगह है।"]],[1856,["लेकिन कब मिली इस आपके एन्क्लेव में,","यह जगह का होना, कुछ मायना रखता है।"]],[1864,["कोई न कोई आप लोगों की पूर्व पुण्याई है,","कोई न कोई विशेषता आप लोगों की है, इसलिए","यहाँ पर ये जगह हो गई है।"]],[1871,["इसमें आपको पैसा देना नहीं है। एक बात समझ लें,","कि परमात्मा को पैसा नाम की चीज़ मालूम ही नहीं है।"]],[1879,["यह इंसान समझ ही नहीं सकता है, उसकी खोपड़ी","में नहीं घुस सकता है कि परमात्मा का कार्य","बगैर पैसे के होता है।"]],[1886,["आप किसी फूल को पैसा देते हैं जब वह फल बन","जाता है या किसी पेड़ के सामने आप ले जा के पैसा"]],[1893,["रख दीजिए, तो वह क्या समझता है कि","यह पैसा है, कि मिट्टी है, कि क्या है?"]],[1901,["परमात्मा ने पैसा नहीं बनाया है, आपने पैसा","बनाया हुआ है, आप ही जानें उसकी दशा।"]],[1908,["इसके लिए आप पैसा नहीं ले सकते न दे सकते।","हाँ एक बात दूसरी, कि आप मेरे लिए फूल ले आए,","चलो ठीक है।"]],[1917,["फूल के लिए आपने दो पैसे खर्च कर दिए, ठीक है।","ये बनाया है, इसके लिए आपने पैसा, ठीक है।"]],[1923,["लेकिन आपकी कुण्डलिनी जागरण के लिए","आपको पैसा नहीं देना है - ये लोग समझते नहीं।"]],[1929,["खासकर, हम देहातों में जाते हैं, तो लोग पाँच","पैसे ले के आए। एक देवीजी बुढ़िया सी आईं,","बड़े प्रेम से मुझे पाँच पैसे दिए।"]],[1937,["मैंने कहा, \"भई ये क्या कर रही हो?\" तो","व्यवस्थापकों ने कहा कि, \"भई, पैसा मत दो।\""]],[1942,["उन्होंने कहा, \"अच्छा भई, माताजी को पाँच पैसा नहीं","पसंद तो दस पैसा ले लो।\" अब उनसे क्या कहा जाए?"]],[1952,["अकल ही इतनी बड़ी तरह है कि उनकी समझ ही में","नहीं आता है, कि जो जीवंत कार्य है, उसमें","पैसा कैसे चलेगा?"]],[1959,["समझ लीजिए किसी का श्वास ठीक नहीं चल रहा।","आप उसके सामने पैसा दिखाईये, वह श्वास","चल जायेगा?"]],[1968,["हाँ, दूसरी तरफ से आप चल सकते हैं, कि अगर","डॉक्टर से दवा लाएँ, ये करें वो दूसरा बात।"]],[1974,["लेकिन जब वो श्वास उसका ख़राब है, जो जीवंत कार्य","है, उसको बदलने के लिए आप पैसा नहीं दे सकते।"]],[1981,["दूसरी चीज़ ये है, कि जितनी भी ज़रूरतें इंसान","की हैं, और जो सबसे महत्वपूर्ण क्रियाऐं हैं,","वो सब अपने आप होतीं हैं।"]],[1994,["उसमें मेहनत करने की ज़रुरत नहीं। जैसे कि हमारा","श्वास ही ले लीजिए। इसके लिए अगर हमें किताबें","पढ़नी पड़ीं, तो हम कितनी देर जीवित रह सकते हैं?"]],[2005,["बहुत से लोग ये सोचते हैं, कि किताब पढ़ कर के","परमात्मा मिलेगा - ये तो और भी पागलपन","की बात है।"]],[2012,["कबीरदासजी ने कहा है कि, \"पढ़ी, पढ़ी पंडित मूरख","भए।\" तो मेरी पहले समझ ही नहीं आता था,","कि पंडित कैसे मूरख हो जायेंगे?"]],[2020,["समझ में नहीं आया। अब मैं ऐसे बहुत देखती हूँ कि,","'इस किताब में ये लिखा है, उस किताब में ये लिखा है'"]],[2028,["अरे भाई, ज़िन्दगी की किताब में क्या लिखा है,","वह देखो। किताब तो जिसके पास थोड़ा सा पैसा हो,","वह लिख देगा।"]],[2037,["आजकल तो ऐसे, ऐसे लोग किताब लिखने वाले","मिल गए हैं - एक साहब ने हमसे भी कहा कि,"]],[2041,["\"आप हमें इतने हज़ार रुपया दीजिए, तो हम आपके","बारे में किताब लिखेंगे।\" मैंने कहा, \"मुझे","आप माफ़ करिए।\""]],[2049,["सो किताब लिखना तो कोई बड़ी भारी बात नहीं और","किताब पढ़ के परमात्मा को पाना, यह भी जो","कल्पनाएँ हैं, बिलकुल गलत हैं।"]],[2057,["इस किताब में लिखा है, वो किताब में लिखा है","- सही है कि नहीं, ये कैसे जानिएगा?"]],[2066,["कोई सी भी किताब हो, मैं तो कहतीं हूँ, दुनिया की।","आपके बच्चे कल कोई भी किताब को नहीं","मानने वाले।"]],[2072,["आप उनके सामने ले जाकर कोई भी किताब","रखिए तो कहेंगे, \"काहे पर से यह बात कही है?","ये किताब काहे पर से कही है?\""]],[2079,["क्योंकि, जिसको आप पढ़ते हैं, आपने कौन से","तीर मार लिए, इसको पढ़ के आपकी कौन सी","खोपड़ी ठीक चल रही है?"]],[2087,["आपमें कौन से गुण आ गए हैं? आप तो जैसे थे","वैसे ही हैं। बस किताबों का बोझा ज़रूर हो","रहा है और घर से पैसा ...।"]],[2097,["बजाय इसके कि आप पहले से ज़्यादा नम्र हो जाएँ","और आपके अंदर बहुत घमंड आ गया है,"]],[2103,["और आप बहुत गुस्सैले हो गए हैं, और आप अपने","को सोचते हैं, कि आप तो के भगवान से भी बढ़के","हो गए हैं, तो ऐसी किताब हम क्यों पढ़ें?"]],[2112,["जो भी किताब हम पढ़ते हैं, वो सही है या नहीं है,","ये जानने का भी तो कोई तरीका नहीं है।"]],[2120,["सब चीज़ों का एक ही तरीका है। जो अपने अंतर","आत्मा है, वह एक है, एब्सोल्यूट है।"]],[2136,["उसको जान लेने से, जो एक एक चीज़ होती है, जिसका","दूसरों से परस्पर सम्बन्ध नहीं होता, जो सम्पूर्ण","होती है, वो चीज़ समझ में आ जाएगी।"]],[2150,["अब जैसे, आज यहाँ संगीत हो रहा था। मैंने देखा कोई","लोग चल के चल दिए यहाँ से, परेशान भी हो गए होंगे,","जिनको क्लासिकल म्यूजिक नहीं अच्छा लगता,"]],[2159,["वो सोच रहे होंगे, \"क्या माताजी ने शुरू कर दिया,","कुण्डलिनी बताने आईं थीं, इनका टुन-टुन","चला दिया।\""]],[2167,["अब जो परदेसी लोग यहाँ बैठे हुए हैं, यह तो","समझते भी नहीं इस टुन-टुन को, ये कौन सा राग","है और ये कौन सा ताल है"]],[2176,["लेकिन ये मज़े में सुन रहे थे और बहुत हमारे","सहज योगी भी सुन रहे थे। वजह ये है कि ये संगीत","आत्मा को छू रहा था।"]],[2186,["अभी तक जब तक वो जागृत नहीं हुआ, तब तक","ये टुन-टुन ही दिखाई दे रहा है।"]],[2192,["जिस दिन जागृत हो जायेगा, उस दिन इससे","जो आपपर असर हुआ है, वो कैसे जानिएगा?"]],[2199,["इसका असर एक सहजयोगी समझता है कि उसके","अंदर से चैतन्य की लहरियाँ बहने लग गईं और बढ़ती","गईं और बढ़ती गईं और आनंद आता गया।"]],[2209,["तो परमात्मा की शक्ति कार्यान्वित होती है, वो","बोलती नहीं है, कार्यान्वित होती है, कार्य को करती है।"]],[2215,["वो जैसे मनुष्य सोचता है कि, \"अब मैंने बैठे-बैठे","सोच लिया।\" अच्छा सोच लिया, तो क्या? सोचने से","आपकी मोटर चलेगी?"]],[2224,["चला के दिखाइये। मोटर में बैठे और सोचते","रहे, सोचते रहे, सोचते रहे।"]],[2229,["\"मैंने सोचा,\" - गया। आपने सोचा, माने इस बुद्धि","से? इसमें कितनी सीमाएँ हैं, आप जानते हैं?"]],[2239,["\"हम तो सोचते हैं।\" आप कैसे सोचते हैं ? उस","सोचने से, आप कौन से कार्य को कर सकते हैं?"]],[2249,["ज़्यादा से ज़्यादा, आप मरी हुई चीज़ की मरी हुई चीज़",".... और खुद भी उनको इस्तेमाल कर-कर के,","मरगिल्ले हो जाते हैं।"]],[2262,["माने ऐसे, कि अब आपने मोटर बनाई, अब मोटर से","आप चलने लगे। आप, मोटर के हो गए आप गुलाम।"]],[2272,["क्योंकि दो टांगें आपकी गईं काम से और अगर किसी","दिन मोटर फेल हो गई, तो आपकी हालत खराब।"]],[2279,["फिर उसके बाद आपका चलना बिलकुल मुश्किल","और आप बैठ गए एक जगह।"]],[2286,["जितनी आपने इस तरह की चीज़ें बनाई हुईं हैं,","ये आपकी खोपड़ी पे लदीं हुईं हैं और उसको लदाने से,","आप सोचते हैं कि आप बहुत बढ़ गए हैं।"]],[2295,["सो आप बाहर बढ़ गए - अंदर इतने से हो गए हैं,","छोटे से। आपकी अपनी कोई शक्ति नहीं रही।"]],[2302,["अपनी शक्ति सिर्फ आत्मा से आती है और उसको","प्राप्त होना चाहिए - ये एक इच्छा पहले करनी चाहिए।"]],[2312,["पहले ये इच्छा करनी चाहिए कि, \"माँ, मैं आत्मा हूँ","और मेरे चित्त में आत्मा का प्रकाश आने दीजिए।\""]],[2321,["जब तक ये इच्छा आपके मन में नहीं होगी,","तब तक मेरा हाथ नहीं चलने वाला।"]],[2327,["पहले इच्छा होनी चाहिए कि, \"मैं आत्मा हूँ","और मैं इस आत्मा को प्राप्त करूँगा।\""]],[2334,["अब माँ का जैसा हाल होता है, कि वह कैस्टर आयल","भी पिलाना चाहे, तो उसमें कुछ कहानी बता के, और","कुछ मीठा-वीठा मिला के चढ़ा देती है।"]],[2346,["लेकिन सच बात आपसे बताऊँ, कि आत्मा को मिलते","ही आप पाइएगा, कि आपका शारीरिक, मानसिक,"]],[2353,["बौद्धिक, जितना भी क्लेश और जितना भी","संघर्ष है सब ख़तम हो जायेगा।"]],[2360,["जो कुछ भी आप दो-चार पीड़ित हैं, वो सब ख़तम","होकर के एक आप दूसरे ही सतह पर, एक दूसरी नगरी","में जा के बैठेंगे, एक दूसरे हो जायेंगे।"]],[2373,["इसीलिए, जिसने ब्रह्म को जाना, उसे द्धिज","कहते हैं, माने जिसका जनम दूसरा हुआ है।"]],[2381,["और बहुत से लोग ऐसे अमेरिका में देखे मैंने, जो अपने","इश्तेहार लगा के घूमते हैं कि, 'हमारा जनम दूसरा","हो गया। \"भई कैसे?\""]],[2389,["भई, आपने कहा कि, 'जनम दूसरा हो गया' तो उसके","कुछ दिखना भी तो चाहिए आसार, कि आप कैसे कह","रहे हैं आपका जनम दूसरा हो गया।"]],[2400,["तो इंसान का जब जनम दूसरा हो जाता है, तो","उसकी जो चेतना है, उसकी जो अवेयरनेस है,"]],[2408,["वह जो महसूस करता है, वो सब कुछ सार्वजानिक हो","जाता है, सामूहिक हो जाता है, कलेक्टिव हो जाता है।"]],[2418,["जैसे बैठे-बैठे यहाँ से आप बता सकते हैं, कि","फलाँ-फलाँ इंसान के कौन से चक्र पकडे हुए हैं।"]],[2429,["सब जानकारी इससे हो सकती है क्योंकि सब चीज़","को जानने वाला आपका आत्मा है। आपकी बुद्धि,","बुद्धि तो यह भी है और वह भी है।"]],[2440,["इसी से आदमी संभ्रान्त है। लेकिन जो सिर्फ है, वो","आत्मा जानता है और जो सच है, वो आत्मा बताता है।"]],[2453,["हम लोग यह बहुत कुछ सुनते आए हैं, अभी तक हर","तरह से लोगों ने समझाया। उसमें सच भी बोलने वाले","बहुत थे और झूठ बोलने वाले भी बहुत हैं।"]],[2464,["बहुत से झूठ बोलने वाले तो ऐसी कॉपी करते हैं","सच बोलने वाले की, कि सच बोलने वाला ही"]],[2470,["अवाक् रह जाता है, कि ये कैसे मेरी ही बात दोहरा","रहे हैं, इतने ज़ोर-ज़ोर से और हिम्मत के साथ।"]],[2476,["और परदेसी लोग तो सोचते हैं, कि भई ये जब बोल","रहा है, तो सच ही होगा, ऐसे झूठ कैसे बोल सकता है?"]],[2481,["उनको नहीं मालूम कि हम लोग झूठ","बोलने में कितने माहिर हैं।"]],[2490,["इसलिए जो कुछ कहा गया, उसका यथार्थ","होना चाहिए, उसका अनुभव आना चाहिए।"]],[2498,["अब बहुत टाइम हो गया है। जो कुछ काम मुझे","करना था वह मैंने संगीत में ही कर दिया है, सिर्फ एक","१०-१५ मिनिट में आप लोग की जागृति हो जाएगी।"]],[2510,["इसमें कोई मुझे शंका नहीं है, लेकिन उसके","बाद योग का जो दूसरा अर्थ है, युक्ति -","'ऐसी युक्ति करो नन्दलाल'"]],[2521,["ऐसी युक्ति, जिससे कि आप अपने आत्मा के बारे में","सब कुछ जान लें, उसकी शक्तियों को पहचान लें,","उसको इस्तेमाल कर लें और सब को इसका लाभ दें।"]],[2534,["जब तक यह नहीं होगा, उसकी कुशलता, जिसे","डेफ्टनेस कहते हैं, जब तक आप नहीं सीखिएगा,"]],[2541,["तो वैसा ही है कि आपके लिए मोटर ला के","रख दी और खड़े खड़े जंग खा गई।"]],[2546,["ऐसा ही योग होता है। हिन्दुस्तानियों पे अधिकतर","योग ऐसा ही देखा है मैंने, कि फिर आ कर के मेरे","सामने जंग की कार खड़ी हो गई,"]],[2554,["और कहने, \"माँ,मैं आपके पास बीस साल पहले","आया था, दस साल पहले आया था, लेकिन फिर","वही जैसा के तैसा हो गया।\""]],[2564,["सो ये बात नहीं है। आपको लगना पड़ेगा, जुटना","पड़ेगा, जानना पड़ेगा, क्योंकि यही एक जानने","का है, बाकी कुछ जानने का नहीं है।"]],[2573,["इसको जान लिया तो आपने सब कुछ जान लिया।","छोटे-छोटे बच्चे भी इसको जान सकते हैं,","अनपढ़ लोग भी इसको जान सकते हैं।"]],[2581,["एक बहुत अनपढ़ आदमी है उन्होंने न जाने हज़ारों","लोगों को सहजयोग के अभ्यास से तंदरुस्त कर दिया,"]],[2591,["उनकी बीमारियाँ ठीक कर दीं, कैंसर जैसी","बीमारियाँ ठीक कर दीं। वह डॉक्टर नहीं है,"]],[2596,["वह डॉक्टरी सीखा नहीं है लेकिन तत्व पे","उतर के उसने ये काम कर के दिखाया है।"]],[2602,["आप भी सब कर सकते हैं। सबसे पहले आप अपने को","ठीक कर लीजिए, अपनी आत्मा से आप इस परम","तत्व को पा लें, उसके बारे में बाद में आप सीख लें।"]],[2612,["खासकर, आप लोगों के लिए यहाँ पे इतने नज़दीक","मंदिर आया हुआ है, कि आप पैदल भी चल के","आ जाएँ, तो भी आप यहाँ पहुँच जायेंगे।"]],[2619,["यहाँ पर आपको रुपया-पैसा देना नहीं है, पहले","ही कहा गया है। सिर्फ आस्था से, अपनी ओर नज़र","कर के, थोड़ी मेहनत करनी है।"]],[2627,["ऐसे हर रविवार को दस बजे सवेरे यहाँ पर प्रोग्राम","होता है। आपको कुछ भी देने का नहीं है,","सिर्फ आपको लेने का है"]],[2636,["और इसलिए अपनी घाघर खाली कर के यहाँ पर","आयें और जो कुछ सीखना है, धीरे-धीरे सीख लें।"]],[2644,["आपको आश्चर्य होगा कि परमात्मा की कृपा कितनी","अपरम्पार है और जो इंसान पार हो जाता है"]],[2650,["उसकी परमात्मा कितनी परवाह करता है","और वह कितना महत्वपूर्ण है।"]],[2655,["आशा है आप लोग मेरी बातों की ओर ध्यान कर के","और हर रविवार दस बजे इस जगह आयें और","सहजयोग के बारे में जानें और सीखें।"]],[2666,["अब सिर्फ आप लोग मेरी ओर ऐसे हाथ कर के और","आँख बंद कर के बैठें और अपना चश्मा उतार लें।"]],[2682,["बंगाल के (अस्पष्ट) लोगों को हमारा प्रणिपात।"]],[2692,["सर्वप्रथम माननीय श्री भगवती प्रसाद जी बनर्जी को","मैं बहुत धन्यवाद देतीं हूँ, कि वह इस गड़बड़ के और","परेशानी व्यस्त जीवन से"]],[2714,["भी निकल कर आज हमारे बीच आए और इतने","गहरे ज्ञान के शब्द आपको सुनाए। ऐसे लोग","आजकल बहुत कम होते हैं।"]],[2730,["मेरा हमेशा विश्वास रहा है कि जो लोग,","लीगल या लॉ प्रोफेशन में रहते हैं, उनमें","धर्म किसी तरह से बसा रहता है।"]],[2738,["मेरे पिता भी लॉयर थे, मेरे पति भी लॉयर थे,","मेरे ससुर भी लॉयर थे। मैं लॉयर की फॅमिली से","आतीं हूँ और मेरे घर में सभी लोग लॉयर्स हैं।"]],[2748,["और एक तरह का धर्म के प्रति जागरूकता मैंने","अनेक लॉयर्स में, यहाँ भी और बाहर हर जगह देखा है।"]],[2761,["हमारे अंदर धर्म की जो व्यवस्था है उसी से","लॉ तैयार होता है। हमारे अंदर दस धर्म जो","कि हमारी दस वैलेंसीस हैं।"]],[2770,["जैसे कि कार्बन की चार वैलेंसी होती है,","ऐसे मनुष्य की दस वैलेंसी होतीं हैं।"]],[2776,["जब मनुष्य उत्थान की ओर आया, जिस वक़्त","उसकी उत्क्रांति हुई, उसका एवोलूशन हुआ, जब","वह एक कार्बन से मनुष्य बना,"]],[2786,["उस वक़्त अनेक तरह की घटनाएँ घटित हुईं,","अनेक अवतरण संसार में हुए, और अंत में वो","मनुष्य स्थिति में पहुँच गया।"]],[2794,["मनुष्य स्थिति में आवश्यक है कि हमारे","अंदर धर्म स्थापना होनी चाहिए।"]],[2800,["लेनिन के बारे में मैं इतना कहूँगी कि लेनिन को मैंने,","उनका शरीर देखा है, मैं रूस गईं हूँ अपने पति के साथ"]],[2807,["वह, आपको आश्चर्य होगा, कि वह साक्षात्कारी पुरुष","थे। साक्षात्कारी थे। बाद में पार्टी की ज़बरदस्ती","से वह इस उस में पड़ गए"]],[2816,["पर उन्होंने जो धर्म के बारे में कहा था, उसका कारण","ऐसा है, कि उस वक़्त रूस में कोई धर्म नहीं था पहले।"]],[2825,["और उसके बाद ज़ार ने कहा कि, \"सबसे पास कुछ न","कुछ धर्म है, हमारे पास भी धर्म आना चाहिए।\""]],[2830,["धर्म के बारे में ये लोग कुछ जानते नहीं हैं,","इनमें कोई गहराई से किसी ने देखा नहीं,","इनमें कोई दृष्टा हुए नहीं।"]],[2836,["अपने यहाँ जैसे बड़े संत-साधु हो गए इस तरह के वहाँ","बहुत ही कम लोग हुए हैं और वह जब बोलते थे,","तो उनको लोग पागल ही समझते थे।"]],[2844,["वहाँ का धर्म जो था, जिसे कहते हैं, बड़ा","ओर्गनाइज्ड, बड़ा सुव्यवस्थित बनाया हुआ।"]],[2849,["उन्होंने परमात्मा को भी सुव्यवस्थित बनाने का","प्रयत्न किया हुआ है। इसलिए लेनिन ने उस वक़्त","जो बात कही वह सही है, एक माने में,"]],[2856,["क्योंकि जब उनके पास कोई धर्म व्यवस्था नहीं थी तो","ज़ार ने कहा कि कुछ न कुछ धर्म व्यवस्था ज़रूर होनी","चाहिए। और इसका मैंने ख़ुद पडताला लिया हुआ है।"]],[2866,["जब हम लोग वहाँ थे तो मैंने कहा कि, \"अच्छा आपके","यहाँ ये जो प्रीस्ट लोग हैं वहाँ मैं जाना चाहती हूँ","और यहाँ के चर्च मैं देखना चाहती हूँ।\""]],[2874,["जब हम गए वहाँ, तो आपको आश्चर्य होगा कि,","वहाँ पर एक ही धर्म है, जिसे कि आप ऑर्थोडॉक्स","ग्रीक क्रिश्चियनिटी कहते हैं।"]],[2882,["और उसमें दो तरह के आर्डर होते हैं - एक तो","ब्लैक और एक वाइट - बहुत ज़्यादा ओवर","ओर्गनइजेड़ चीज़ होती है।"]],[2887,["और वह महाशय जब हम वहाँ पहुँचे, क्योंकि","हम लोग वी आई पी थे, तो वह स्वयं आए"]],[2893,["और वहाँ के जो मुख्य थे उन्होंने हमसे कहा कि,","\"आजकल हम फास्टिंग कर रहे हैं लेकिन इसकी वजह","से हम वेजीटेरियन खाना खाएँगे।\""]],[2901,["तो हमने कहा, \"वो तो बहुत अच्छी बात है","वेजीटेरियन खाना खाएँगे।\""]],[2904,["लेकिन उनको वेजीटेरियन खाना खाने में हर्ज़,","मतलब नॉन-वेज खाने में हर्ज़ नहीं था,"]],[2911,["लेकिन वह शराब इतनी पी गए, इतनी शराब पी गए","वह महाशय, कि जब हम आने लग गए तो उनको","होश ही नहीं था कि चीफ गेस्ट जा रहे हैं"]],[2918,["या उनको सी ऑफ करना चाहिए - इतनी शराब वो","पी गए। तो मैंने पूछा कि, \"ये कैसे लोग यहाँ","आ गए, ये क्या है?\""]],[2924,["तो उन्होंने बताया, कि जब ज़ार ने ये इच्छा प्रदर्शित","की कि, यहाँ पर कोई तो भी धर्म होना चाहिए,","तो कहने लगे, \"अब कौन सा धर्म करें?\""]],[2932,["तो उन्होंने कैथोलिक से पूछा, तो कैथोलिक ने कहा,","\"भई हमारे धर्म में एक बात है, तुम शराब तो पी सकते","हो लेकिन तुम दूसरी शादी नहीं कर सकते।\""]],[2939,["ज़ार ने कहा, \"ये तो नहीं सम्भव क्योंकि हमारे पास","तो बहुत शादियाँ करने के प्रस्ताव होते हैं तो ये कैसे","हो सकता है, ये हमें चलेगा नहीं।\""]],[2946,["इसलिए उन्होंने उसको मना कर दिया। दूसरे","उन्होंने कहा, \"अच्छा, अगर ये चीज़ नहीं,","तो दूसरा धर्म कोई देखें।\""]],[2951,["मुसलमान आए। मुसलमानों ने कहा, \"भई हमारे यहाँ","व्यवस्था है, आप अधिक शादियाँ कर सकते हैं,","लेकिन हमारे यहाँ शराब पीने की व्यवस्था नहीं है।\""]],[2959,["शराब नहीं पी सकते। उन्होंने कहा, \"ये तो","बिलकुल हमारे यहाँ चल ही नहीं सकता धर्म।\""]],[2963,["तो तीसरा, एक ग्रीक ऑर्थोडॉक्स एक","धर्म नया निकला था, वह आया।"]],[2968,["उसने कहा, \"भई, हमको कुछ नहीं मतलब। आपको","जो करना है करो, सिर्फ हमें पैसा देते रहो,\"","- जैसे आजकल के गुरु हैं।"]],[2975,["जब उसको लेकर के अगर लेनिन ने यह बात कही तो","सत्य बात है। उन्होंने जो बात कही थी वो","इंटरमीजियरी बात थी।"]],[2983,["हम लोग न तो कैपिटलिस्ट हैं, न कम्युनिस्ट","हैं, और हैं दोनों ही।"]],[2987,["जब आपके पास सब शक्तियाँ आ जातीं हैं","- समझ लीजिये हमारे पास सब शक्तियाँ हैं,"]],[2992,["तो हम कैपिटलिस्ट हो गए, लेकिन चैन से बैठा","नहीं जाता बांटे बगैर, तो कम्युनिस्ट हो गए।"]],[2999,["जब शेयरिंग के बगैर चैन ही नहीं आ रहा,","तो कम्युनिस्ट हो गए।"]],[3002,["असल में जो कुछ आपकी थियोरीस हैं, उसकी","रियलिटी आपको जो है, असलियत, जब आप","आत्मज्ञान पाएँगे तब होगा"]],[3010,["क्योंकि ये भी सब आपके अचेतन से,","अनकॉन्ससियस से आई हुई धारणाएँ हैं,"]],[3015,["कि हम कम्युनिस्ट हैं, कोई कहते हैं हम","कैपिटलिस्ट हैं - ये सब बाह्य की बातें - काहे का","कैपिटल है इनके पास - ये पत्थर?"]],[3023,["इनके पास अगर कैपिटल होता तो आज क्यों रोते","रहते? जो बड़े भारी कैपिटलिस्ट हो गए हैं,"]],[3027,["ऐसे तीन देश आप जान सकते हैं स्विट्ज़रलैंड,","नॉर्वे और स्वीडन। तीनों देशों में कॉम्पिटेशन","ये उन लोगों में रहता है,"]],[3035,["कि कौन पहले मरेगा और कौन आत्महत्या","करेगा? ये क्या कैपिटैलिस्म है?"]],[3040,["उनको तो कोई भोग नहीं हुआ उसका। जिसने","भोगा ही नहीं, उसका कैपिटल किस काम का?"]],[3045,["तो हमारी भी जो कल्पना है, कि हमें पैसा मिलने से या","आर्थिक व्यवस्था ठीक हो जाने से, हम बिलकुल","बढ़िया हो जायेंगे - बिलकुल ग़लतफहमी है।"]],[3053,["क्योंकि हम पैसा नहीं बर्दाश्त कर सकते। आप","किसी आदमी को 100 रुपया दे दीजिए, फ़ौरन","वो जायेगा शराब पीने के लिए।"]],[3063,["कोई सा भी गलत काम। जितने पैसे वाले लोग","हैं, वो गलत काम में फँसे रहते हैं।"]],[3068,["उनके अंदर कभी पैसे की वजह से कोई","सुबुद्धि आते हुए आपने देखा है?"]],[3072,["फिर लोग ये सोचते हैं कि चलो नहीं सत्ता ले लें।","जिसके पास सत्ता आ गई, वो तो बिलकुल","पागल आदमी हो जाता है।"]],[3079,["उससे तो आप बात भी नहीं कर सकते। इसलिए सत्ता","की ओर भी जिनका ध्यान है, कि हम सत्ता को पाकर","के ही खुश हो जाएँ, सो भी बात नहीं।"]],[3086,["कोई कहते हैं कि, \"चलो हमारे माँ- बेटे, हमारी","माँ-बहन इनको संभाले\" - अपने देश में तो पागलपन","लोगों पे सवार है।"]],[3092,["'मेरा बेटा, मेरी बेटी, मेरा, मेरा,' इतना","ज़्यादा है कि उसकी भी अतिशयता है।"]],[3098,["इसपे श्री कृष्ण ने बहुत अच्छा दर्शन दिया","हुआ है, कि संसार में तीन तरह के लोग हैं,","तीन ही जाति हैं।"]],[3104,["जो हम लोग जाति-जाति का झगड़ा करते हैं,","इतनी जाति नहीं हैं - सिर्फ तीन जाति हैं।"]],[3108,["चौदह हज़ार वर्ष पूर्व मार्कण्डेय स्वामी ने कहा था,","'या देवी सर्व भूतेषु जाति रूपेण संस्थिता' तीन ही","देवियाँ हैं -"]],[3115,["महाकाली, महालक्ष्मी, महासरस्वती - तीन देवियाँ हैं।","उसी के अनुसार तीन गुण हमारे अंदर होते हैं।"]],[3121,["एक तो तामसिक, एक राजसिक और एक सात्विक।","जो तामसिक लोग होते हैं, वह गलत चीज़ को ही","सही समझ लेते हैं।"]],[3129,["अपने देश में अधिकतर लोग, मेरे ख्याल से, तामसिक","हैं। कोई भी आदमी जेल से छूट के आए, गेरुआ वस्त्र","पहन ले, और लगे उसके पैर छूने।"]],[3138,["वह आदमी कौन है, कहाँ से आया है, क्या करता है,","पता नहीं। तांत्रिकों से तो, मुझे लगता है,","कलकत्ता भरा पड़ा है।"]],[3144,["जिस इंसान को मैं मिलतीं हूँ कहे, \"मैं तो दीक्षित हूँ,\"","और कुण्डलिनी तो जमी हुई है, दीक्षित कैसे हैं आप?"]],[3149,["गलत चीज़ के पीछे में पड़े रहना, ये तामसिक लक्षण","है। गलत चीज़ को सही मान के उसके लिए अपना","जीवन दे देना, तामसिक लक्षण है।"]],[3157,["फिर कोई लोग हैं अपनी पत्नी के लिए करते","हैं, कोई अपने बेटे के लिए करते हैं।"]],[3161,["कोई न कोई इस तरह की गलत चीज़ ले कर के काम","करना, जिसका सामूहिक से कोई सम्बन्ध नहीं है,"]],[3167,["जिसका कलेक्टिव से कोई सम्बन्ध नहीं है,","ऐसे कार्य करना, ये तामसिक लक्षण है।"]],[3172,["और राजसिक लक्षण ये होता है कि जैसे पाश्चिमात्य","देशों में लोग होते हैं कि उनको सही और गलत","दोनों का फर्क ही नहीं मालूम।"]],[3181,["अगर आपसे, जैसे लंदन में कुछ लोग हमारे पास आए,","तो गुलाबी रंग के बाल, यहाँ पर उन्होंने पिने लगाई","हुईं हैं, यहाँ पर ४-५ पिने लटक रहीं,"]],[3190,["मैंने कहा, \"भई, ये क्या अवतार है?\" तो उन्होंने","पूछा, \"व्हाट'स रॉन्ग - इसमें खराबी क्या है?\""]],[3194,["अब क्या कहा जाए बेवकूफ़ों को, कि इसमें क्या खराबी","है। आप सारी पिनें यहाँ से लटका लीजिए सब, तो","उसको क्या खराबी हो सकती है?"]],[3200,["लेकिन इन लोगों को यही नहीं पता - आप लोग क्यों","वेस्टर्न लोगों को फॉलो कर रहे हैं? इनको तो यह नहीं","पता, कि अच्छा क्या है और बुरा क्या है?"]],[3207,["महामूर्ख की स्थिति है, महामूर्खता। उनकी बातें","सुनिए तो आश्चर्य होता है। एक से एक बढ़के हैं।"]],[3213,["हम बोस्टन गए थे। वहाँ कहा गया कि, \"माताजी","आईं हैं, तो उनके लिए ऐडवरटीसमेन्ट रखेंगे।\""]],[3219,["उन्होंने पूछा, \"उनके पास कितने रोल्स रॉयस हैं?\"","तो वह तो पैसा-वैसा लेते नहीं, उनके","स रोल्स रॉयस कहाँ से ?\""]],[3224,["कहने लगे, \"फिर हमको ऐसे आदमी में इंटरेस्ट","नहीं जिसके पास रोल्स रॉयस नहीं।\""]],[3227,["उन्होंने कमर्शियल इतना बना दिया है,","कि भगवान भी कमर्शियल हो गया है।"]],[3232,["और इसीलिए यहाँ से जितने कमर्शियलाईजेड गुरु","थे, सब जाके वहाँ बैठ गए अपना नसीब है।"]],[3237,["लेकिन अब समझना यह चाहिए, कि तीसरा जो था,","वो सात्विक है। सात्विक आदमी जो होता है वो","जानता है, अच्छा क्या और बुरा क्या।"]],[3245,["धर्म क्या है, अधर्म क्या है? दोनों चीज़ को जो","समझता है, वही सात्विक आदमी है और ऐसे आदमी","का उत्थान हो सकता है।"]],[3252,["और ऐसा ही आदमी आत्मा को प्राप्त कर। बहुत से","लोग ये भी पूछते हैं, \"माँ धर्म की स्थापना क्यों करें?"]],[3259,["हमारे अंदर जो दस वैलेंसीस हैं,","इनको हम क्यों स्थापित रखें?\""]],[3263,["वजह ये है, कि गर आपको आत्मा बनना है,","अगर आकाश में उड़ना है, तो आपको चाहिए","कि आपको संतुलित हो जाएँ।"]],[3271,["और इसीलिए हमारा जो कायदा है, कानून है, यह","संतुलन पे बना हुआ है कि असंतुलन में कहीं भी","एक्सट्रीमस पे चले जाइए -"]],[3279,["राइट साइड में आप चले जाते हैं जबकि आप राजसिक","हो जाते हैं, तो आप दूसरों पे इस तरह से अमानुष","अत्याचार करते हैं,"]],[3286,["उनके साथ दुर्व्यवहार करते हैं और उनपर","हावी रहते हैं, उनपर अग्रेशन करते हैं।"]],[3291,["और जिस वक़्त में आप तामसिक हो जाते हैं, तो आप","अपने ही को मारते हैं, अपने ही साथ दुष्टता करते हैं,"]],[3298,["खाते नहीं, पीते नहीं, उपास करते हैं, दुनिया भर की","चीज़ें करते हैं जिससे अपना शरीर नष्ट हो जाए।"]],[3304,["इतनी गलत धारणाएँ अपने देश में बनीं हुईं हैं,","कि उसको एक-एक को तोड़ते-तोड़ते, हमारे तो","बारह-चौदह साल का हो गया तब"]],[3311,["लेकिन अब मुझे ये है कि मैं आज प्रथम आप लोगों","के सामने आई हूँ, इसलिए मुझे आपसे विनती है,"]],[3317,["कि एक सिर्फ आप अपने अंदर धारणा रखें, कि जो","बात हम जानेंगे अनुभव से, वही बात सही है।"]],[3324,["अनुभव शून्य बातचीत, सिर्फ बातचीत रह जाती है,","जिसे कि शंकराचार्य ने कहा, 'ये शब्द जालम है'।"]],[3330,["फिर बहुत से आडम्बर लोग करते हैं, दुनिया भर","के तमाशे - कोई इस तरह का नाचना, कूदना","- ये सब आडम्बर है।"]],[3337,["योग अंतर्योग है, अंतर योग है। आपके अंदर ये","घटना घटित होती है, जो कुण्डलिनी का जागरण है।"]],[3343,["मैंने तो ऐसी भी किताबें देखीं हैं जिसमे लिखा है","कि, कुण्डलिनी के जागरण से ये बीमारी होती है,","वो होता है - कभी भी नहीं होने वाला।"]],[3350,["क्योंकि कुण्डलिनी जो है ये आपकी अपनी माँ है।","हर एक आदमी के पास उसकी कुण्डलिनी त्रिकोणाकार","अस्थि में बैठी हुई है"]],[3360,["इस इंतज़ार में, इस मौके का वह इंतज़ार कर रही है,","कि ये मेरा बेटा कब इस ओर मुड़ेगा और कब","उसे मैं पुनर्जन्म दे सकती हूँ।"]],[3369,["ये आपकी शुद्ध इच्छा है। बाकी जितनी भी इच्छा","संसार में होती है वो अशुद्ध हैं, शुद्ध नहीं हैं।"]],[3375,["उसकी वजह ये है कि आप जानते हैं कि","इकोनॉमिक्स (अर्थशास्त्र) में ये माना जाता है"]],[3379,["कि जो इच्छाएँ हैं, डिसायअरस हैं, वो आपकी, इन","जनरल, माने पूरी तरीके से कभी भी नहीं होतीं हैं"]],[3387,["लेकिन हाँ एक दो हों इन पर्टिक्युलर, वह ख़तम","हो जातीं हैं। माने ये, कि आज हम कहेंगे कि,","\"हमारे लिए मोटर चाहिए,\" मोटर आ गई,"]],[3393,["फिर हमको घर चाहिए, फिर घर चाहिए तो हमको","ये चाहिए - ये इच्छाएँ चलतीं रहेंगीं।"]],[3397,["पर जो शुद्ध इच्छा है, वो आपकी कुण्डलिनी है।","ये परमात्मा की शक्ति है। ये आदिशक्ति की","आपके अंदर उसका प्रतिबिम्ब है।"]],[3405,["इस आदिशक्ति को सिर्फ एक ही चीज़ चाहिए।","वह एक ही चीज़ मांगती है कि उस निराकार ब्रह्म","से एकाकार हो जाए।"]],[3414,["परमात्मा की जो सर्वव्यापी शक्ति है, उससे मैं","एकाकार हो जाऊँ। बस यही एक शुद्ध इच्छा है।"]],[3420,["जब तक वो इच्छा पूर्ण नहीं होती, तब तक बाकी सब","इच्छाएँ आती हैं, जातीं हैं, ख़तम हो जातीं हैं।"]],[3425,["लेकिन जब ये इच्छा जागृत हो जाती है -","और मनुष्य तब उसको साधक कहतें हैं -"]],[3430,["और इसकी जागृति के बाद जब मनुष्य उसे पा लेता है,","पाने के बाद फिर उसे पाने का कुछ नहीं रह जाता,","फिर देने का हो जाता है।"]],[3437,["जैसे कि एक दीप है, जब तक नहीं जला है, तब उसे","सजोया गया, बनाया गया, उसमें तेल डाला गया, बाती"]],[3443,["जब उसको बार दिया, तब उसका काम","शुरू हो गया देने का।"]],[3446,["इसी प्रकार मनुष्य को भी परमात्मा ने इतना","सुन्दर बनाया है इतना संजो कर बनाया है"]],[3451,["ये कहना कि परमात्मा नहीं है, इसमें भी कोई","हर्ज़ नहीं। कहो चाहे न कहो, है तो है।"]],[3456,["लेकिन जब कोई कहता भी है, \"परमात्मा नहीं है,\"","तो भी वो कहता है कि है। नहीं कहने का मतलब","भी है, होता है।"]],[3462,["और इसलिए जो मनुष्य कहता है कि परमात्मा है","ही नहीं, उसकी सिद्धता देने का आज समय","आ गया है।"]],[3470,["हाँ, पहले एक दो लोग ही पार होते थे, एक दो ही","संत होते थे, एक ही दो लोगों को ये प्राप्त होता था।"]],[3479,["क्योंकि जैसे जीवन्त कोई पेड़ हो, उसके","अंदर पहले एक दो ही फूल लगते हैं"]],[3486,["पर जब बहार आ जाती है, अनेक फूल जब उस पेड़","पर आ जाते हैं, तब अनेक उसमें से फल निकलते हैं।"]],[3494,["इसीलिए सहज योग आज समुदाय में होता है,","सामूहिक। ये एक दो के लिए नहीं, यह समाज की","तरफ उन्मुख है।"]],[3502,["समाज की तरफ इसकी दृष्टि है। इसकी वजह से","अगर समाज में शुद्धिकरण नहीं होगा, तो","सहज योग व्यर्थ है।"]],[3511,["यह शुद्धिकरण का एक मार्ग है, मनुष्य के परिवर्तन","का, पूर्णतया उसके पुनर्जन्म का एक मार्ग है,","जिससे मनुष्य पूर्णतया बदल जाता है।"]],[3520,["जो आदरणीय ट्रस्टी साहब ने बात कही, कि","हमारे अंदर इक्वालिटी आनी चाहिए।"]],[3526,["इक्वालिटी बाह्य से, और सिर्फ मेन्टल प्रोजेक्शन से","या थॉट(विचार) से कभी भी नहीं आएगी। जो भी","आएगी, वह सिर्फ दिखने वाली होएगी।"]],[3534,["मैंने ऐसी इक्वालिटी कहीं दुनिया में नहीं देखी।","लेकिन जब आपका आत्मा जागृत हो जाता है,"]],[3539,["तब आपके अंदर एक नया आयाम, एक नया","डायमेंशन, आपके सेंट्रल नर्वस सिस्टम पे ,","आपके नसों पे आ जाता है,"]],[3547,["और आप महसूस करते हैं कि आप सामूहिक चेतना से","चेतित हुए हैं। यह कोई दिमागी जमा खर्च नहीं रहता।"]],[3555,["ये वासत्विकता आप महसूस करते हैं, कि दूसरे आदमी","के चक्र कहाँ पकड़ रहे हैं, आपके चक्र कहाँ पकड़ रहे हैं,"]],[3562,["उनकी कुण्डलिनी कहाँ है, आपकी कुण्डलिनी कहाँ","है - जैसे कि दूसरा कोई रह ही नहीं जाता।"]],[3567,["लोग बहुत से, आपने सुना होगा कि, मिशनरी","जैसे काम करते हैं, कि गरीबों को उठा के लाओ,","उनको ये करो, वो करो,"]],[3575,["इसमें परमात्मा का कोई हाथ नहीं। गरीबी आपने","बनाई हुई चीज़ है, परमात्मा ने किसी को","गरीब नहीं बनाया था।"]],[3580,["वो गरीबों को उठा के उनकी मेडिसिन दे दी और उसको","परमात्मा का नाम देने की कोई ज़रुरत नहीं।"]],[3585,["जिस वक़्त आप आत्मसाक्षात्कारी होते हैं, आप","किसी को कुछ देने की ज़रुरत नहीं होती,","अपने आप घटित होता है।"]],[3592,["हो सकता है, कि आज यहाँ बैठे हुए लोग बहुत सारे","स्वस्थ हो जाएँ। ऐसी आपकी कुण्डलिनी जागृत हो","जाएगी, आपकी तंदरुस्ती ठीक हो जाएगी।"]],[3600,["इससे जितने भी दुर्धिर, जैसे कि कैंसर, जिसको कहा","जाता है कि इनक्योरिबल डिजीजेस, ऐसे कितने ही","इससे ठीक हो जाते हैं।"]],[3611,["क्योंकि आपकी जो शक्ति कुण्डलिनी जागृत हो गई,","तो उसने वह सारे चक्रों को प्लावित कर दिया"]],[3618,["और उसकी वजह से वह चक्रों में बैठे हुए जो देवता हैं,","वो जागृत होने से, आप फिर से स्वस्थ हो गए।"]],[3623,["इसमें कोई विशेष बात नहीं, इसमें कुछ करना","नहीं होता, मेरा लेना देना कुछ नहीं लगता।"]],[3628,["मेरा तो ये कहना है कि अगर एक ऊँगली में दर्द है,","और दूसरी ऊँगली से अगर उसको रगड़ दिया जाए,"]],[3633,["तो क्या ये ऊँगली उसके लिए उपकार मानेगी","या कुछ? वह तो करना ही है, वह तो करना ही है","क्योंकि वो शरीर का एक अंग प्रत्यंग जब हो गया।"]],[3642,["इसी प्रकार आप दूसरे ही नहीं रह जाते","और ये दशा आने पर यह नहीं रहता"]],[3648,["कि मैंने आपके ऊपर उपकार किया है, कि मैंने","आपके साथ भलाई करी है - ये भाव ही छूट जाता है।"]],[3653,["ये तो सिर्फ बहते रहता अकर्म में, जैसे सूर्य","का प्रकाश बहता है। लेकिन, तो भी, हमारी","बुद्धि जो है बड़ी तीक्ष्ण है।"]],[3660,["हर एक चीज़ हम बुद्धि से देखते हैं और","बुद्धि से जानने के प्रयत्न में रहते हैं।"]],[3663,["हाँलाँकि सहज, सहज माने, 'सह' आपके साथ जन्मा","हुआ, ऐसे ये योग का अधिकार, आपका अपना स्वयं","है। ये आपका जन्मसिद्ध अधिकार है।"]],[3672,["स्वातन्त्र जिसे हम कहते हैं, वह स्वातन्त्र","अभी तक नहीं मिला। अगर मिला होता, तो ये","हालत अपने देश की न होती।"]],[3678,["शिवाजी ने कहा था जिस वक़्त उनका राज्याभिषेक","हुआ - तो रामदास स्वामी स्वयं ब्राह्मण थे -"]],[3683,["लेकिन उन्होंने आकर के शिवाजी से यह बताया कि,","'स्व धर्म जागो (अस्पष्ट - आवा ?)', स्व का धर्म","जागृत करो,"]],[3689,["स्व का धर्म जागृत जब तक नहीं होगा, तब तक देश","का कल्याण नहीं होगा। स्वतंत्रता तो हो गई, लेकिन","उन्होंने कहा, कि यह तो स्वातन्त्र है।"]],[3697,["स्व तंत्र होना चाहिए। 'स्व' माने आत्मा का जो","तंत्र है, तकनीक, जब तक उसे नहीं जागृत करोगे","तब तक ये कार्य नहीं होगा।"]],[3703,["हाँलाँकि महाराष्ट्र में, इस पर बहुत कार्य हुआ है","कुण्डलिनी पर। वजह ये है कि उस देश में बड़े-बड़े","संत-साधुओं ने इस पर बड़ी मेहनत करी हुई है।"]],[3713,["खासकर ज्ञानेश्वर जी ने कहा है कि जो, उन्होंने","कहा है कि 'अब विश्वातपक जो है वो खुश हो हमसे","और खुश हो कर के तोषावे'।"]],[3722,["तोश - तोश के साथ हमे पसायदान दें।","माने ये वाइब्रेशन्स दें, ये चैतन्य दें।"]],[3727,["और 'स्वधर्म सूर्य विश्व पाहुक' - माने स्वधर्म","का सूर्य सारा विश्व जाने।"]],[3738,["जिस वक़्त यह स्वधर्म का हमारे अंदर जागरण","नहीं होता है, हम सिर्फ ज़बानी, मेन्टल प्रोजेक्शन में","कहते रहते हैं, कि हम भाई-भाई हैं।"]],[3747,["हम कहते थे 'चीनी, हिंदी भाई-भाई' कहाँ गया","वो? हम आपस में ही भाई-भाई नहीं। आपस में नहीं।"]],[3753,["आपस में हिन्दुस्तानियों के लिए तो विशेषता है कि,","एक दूसरे का जब तक गर्दन नहीं काटें,","उनको चैन नहीं आए।"]],[3758,["तो कहाँ हुए हम भाई-भाई? कहने की बात है कि हम","भाई हैं और दोस्ती है। दोस्ती कहीं नहीं हो सकती","जब तक आप आत्मा में जागृत हो नहीं सकते।"]],[3768,["क्योंकि आपके अंदर जो सामूहिक व्यष्टि है, जो,","वो समष्टि जो आपके अंदर है, वो आत्मा से ही","पाई जाती है।"]],[3777,["जो आपके अंदर कलेक्टिव बीइंग है, वो आत्मा है। वो","जब तक आपने पाया नहीं, आप सब भिन्न-भिन्न","अलग हैं"]],[3786,["और उसका भी कारण है, सब को अलग बनाया गया,","इसलिए कि हर आदमी अपने व्यक्तिगत दिशा में","पहले ये जान ले, अच्छा क्या, बुरा क्या?"]],[3796,["अपनी पहले स्वतंत्रता को जाँच ले। अगर वो मध्य","मार्ग में रहता है, तो फिर वो उस आत्मा को प्राप्त","कर सकता है,"]],[3803,["जिस आत्मा से वह सारे कलेक्टिव में जागृत हो जाता","है। तो जो बातें हम लोग सोचते हैं कि सब समाज के","लिए होनी चाहिए, वो कैसी होंगी?"]],[3811,["कोई तरीका है, आप बता दीजिए? कोई आदमी","कि जिसको आपने सत्ता पे बैठा दिया,"]],[3816,["वो बिलकुल ही निःस्वार्थ, बिलकुल ही किसी","आइडियोलॉजी के बगैर, बिलकुल ही किसी एक","डोग्मा के बगैर, कभी रही नहीं सकता।"]],[3825,["उसके दिमाग में वह बनता ही जायेगा, क्योंकि","अभी उसका ब्रह्मरंध्र का छेद नहीं हुआ है।"]],[3830,["जब ब्रह्मरंध्र छिद जाता है, तो वह उस परमात्मा","के असीम, ऐबसोल्यूट, एकमेव शक्ति से","एकाकार होता है।"]],[3838,["उसमें दो सवाल नहीं होते। सत्य दो","कभी नहीं होते।"]],[3842,["अब आपसे हम ऐसे बताएँ, कि जैसे कि आपने","किसी आदमी को देखा, तो क्या आप बता सकते हैं","ये आदमी अच्छा है, बुरा है?"]],[3849,["नहीं बता सकते। एक आदमी कहेगा, \"बड़ा अच्छा","है,\" एक कहेगा, \"बुरा है।\""]],[3852,["लेकिन जब आप आत्म का साक्षात्कार पाते हैं, तो","आपके अंदर चैतन्य की लहरियाँ बहने लगतीं हैं,"]],[3858,["अगर वह आदमी ख़राब होगा, तो आपकी लहरियाँ","एकदम बंद हो जायेंगीं। मानो कि एक आप कंप्यूटर हैं।"]],[3863,["आप वैसे भी कंप्यूटर ही हैं। इतने विशेष कंप्यूटर हैं,","कि बगैर कुछ सोचे समझे, कुछ प्रोग्रामिंग के ही,"]],[3869,["कोई चीज़ देखते ही आप जान जाते हैं, हाँ आप क्या हैं।","लेकिन वह कंप्यूटर चलने तब लगता है जब कि","उसका सम्बन्ध मेंस से हो जाता है।"]],[3876,["जैसे ये भी एक है इंस्ट्रूमेंट(यन्त्र) यहाँ। जब तक","इसका कनेक्शन मेंस से नहीं होगा, ये व्यर्थ है।"]],[3883,["इसी प्रकार हमारा भी कनेक्शन मेंस से होना","चाहिए। अब भक्ति में लोग भगवान का नाम","लेते हैं, चिल्लाते हैं, चीखते हैं।"]],[3890,["आप ऑक्सफ़ोर्ड स्ट्रीट में देखिये तो आप शर्म","से मर जाएँ, कि वह लोग धोती पहन-पहन कर के,"]],[3895,["और बाजार में उनकी बोदियाँ मिलतीं लगा-लगा","करके, रास्ते में ढोलक बजा-बजा करके, और","सब धोती भी गिरती, साडी भी गिरती,"]],[3901,["कोई तमीज़ नहीं, कुछ नहीं, बुद्धू जैसे, 'हरे रामा,","हरे कृष्णा' करते हुए भीख मांगते हैं।"]],[3906,["वह जो कृष्ण जो साक्षात लक्ष्मीपति हैं, उसके","ये भक्त लोग इस तरह से भीख माँगते हैं।"]],[3915,["भीख माँगना लक्ष्मीपति के पुत्र को शोभा नहीं","देता। लेकिन ये है नहीं, ये कोई जमात और है,","जो गलत चीज़ के पीछे में पड़ी हुई है।"]],[3924,["श्री कृष्ण ने साफ़ कहा है 'योगः क्षेमः वहामयम'।","हम इस बात को भूल जाते हैं कि कृष्ण डिप्लोमेट","थे, डिप्लोमेसी का एक आवेषण थे।"]],[3932,["वो जानते थे कि मनुष्य ज़रा डाँवाँडोल चलता","है। इससे सीधी, सीधी ऊँगली घी नहीं निकलेगा।"]],[3937,["उन्होंने साफ़ कहा था, 'योगः क्षेमः वाहमयम'।","पहले योग को प्राप्त करिए फिर क्षेम होगा।"]],[3943,["'क्षेम योग' कभी नहीं कहा या 'क्षेम' भी नहीं","कहा कि उस समय (अस्पष्ट - वहन?) करता।","'योगः क्षेमः वाहमयम'"]],[3948,["भक्ति पर भी उन्होंने कहा है कि, 'पत्रं, पुष्पं, फलं,","तोयम,' जो भी दो ले लूँगा लेकिन कौन सी","भक्ति चाहिए 'अनन्य'।"]],[3956,["मतलब ये, कि जब आत्मसाक्षात्कार में आप अनन्य,","जब कोई - अनन्य मानें, जब दूसरा कोई","नहीं रह जाता है।"]],[3961,["तो दशा ये है, कि उस वक़्त दूसरा कोई नहीं रह जाना","चाहिए, आपकी एकाकारिता परमेश्वर से होनी चाहिए।"]],[3967,["दिखने को बात लोगों को लगता है कि,","\"माँ ऐसे कैसे, इतने सरल कैसे हो सकता है?\""]],[3971,["खासकर जो बुद्धिवादी होते हैं, वह कहते","हैं, \"इतना सरल कैसे हो सकता है?\""]],[3974,["लेकिन यह जीवन्त क्रिया है। जीवन्त परमात्मा","की जीवन्त क्रिया हमेशा सहजयोग ही है।"]],[3980,["आप सोचिये कि हमारे श्वास-ओ-श्वास के लिए हमें","अगर किसी गुरु के पास जाना पड़े और कोई किताब"]],[3984,["पढ़नी पड़े और उसके लिए इनीसिएशन लेना","पड़े तो क्या फायदा, कोई जी सकता है?"]],[3989,["कोई सी भी जीवन्त क्रिया आप देख लीजिए। एक बीज","है उसको आप सिर्फ इस माँ के गोद में डाल दीजिए,","वह अपने आप अंकुर जाता है।"]],[3998,["कैसे अंकुरता है, कोई बता सकता है? क्यों","अंकुरता है, कोई बता सकता है?"]],[4001,["कोई नहीं बता सकता। साइंस नहीं बता सकता","इस बात को, कि वह किस तरह से, क्यों,"]],[4005,["किस शक्ति की वजह से अंकुरता है। उसमें कौन","सी ऐसी शक्ति है जिससे वह अंकुरता है।"]],[4010,["हम तो कोई भी जीवन्त कार्य नहीं करते लेकिन","इतना अहंकार हमारे अंदर है जिसकी कोई हद्द नहीं।"]],[4015,["हम लोग अब समझ लीजिए एक पेड़ है गिर गया","उससे हमने बना दी कुछ बना दिया, समझ लीजिए,"]],[4019,["स्टेज बना दिया, तो हम सोचते हमने बड़ा भारी","काम कर दिया। ये पत्थर पड़े थे उससे अगर","बिल्डिंग बना दी -"]],[4024,["मरे से मरा बनाया आपने - जीवन्त कार्य","आजतक कौन सा किया आपने?"]],[4027,["सिर्फ जब आप आत्मसाक्षात्कारी होते हैं, तब आप","जीवन्त कार्य कर सकते हैं, क्योंकि आपके हाथ से","कुण्डलिनी का जागरण होता है।"]],[4035,["अब इसके बारे में कितना भी बताया जाए, तो भी","आपके समझ में नहीं आएगा जब तक आपको","इसकी अनुभूति नहीं आएगी।"]],[4041,["अनुभूति ज़रूर आनी चाहिए। बगैर अनुभूति के","बातचीत करने में सिर्फ समय बर्बाद करना है।"]],[4047,["जैसे समझ लीजिए कि आपको इस कमरे मैं आना है,","और आपने पूछा कि, \"माँ, ये लाइट कैसे जलाना है?\""]],[4053,["मैंने कहा, \"अच्छा बेटे, वो जो स्विच है उसको ऑन कर","दो।\" आपने जा के स्विच ऑन कर दिया, हो गया।"]],[4058,["लेकिन यह मतलब नहीं इस लाइट के पीछे में","कोई और लाइट नहीं है, इसके पीछे में कोई और","बड़ी भारी संस्था नहीं है,"]],[4065,["और उसके पीछे में बड़ी भारी हिस्ट्री नहीं है","और इसका बड़ा भारी एक शास्त्र नहीं है -"]],[4070,["सब है, लेकिन आपके लिए सारा आसान बना दिया है,","क्योंकि जब सामूहिक पर कार्य होना है, तो","इसको आसान ही बनाना पड़ेगा।"]],[4077,["सर्वजन साधारण को जब तक कुण्डलिनी का","जागरण नहीं मिलेगा परमात्मा का नामों-निशाँ","शायद संसार से मिट जाए।"]],[4085,["सर्वजन साधारण को इसका लाभ होना चाहिए","और यही मेरा प्रयत्न रहा। मैं जब पैदा हुई थी,"]],[4090,["पिता मेरे बारे में जानते थे कि मेरा क्या कार्य","है और उन्होंने मुझे बताया था कि,"]],[4094,["\"बेटी तुमको चाहिए कि तुम अभी कुछ बातचीत","नहीं करो, इसके बारे में कुछ मत बोलो,"]],[4098,["क्योंकि दूसरा गीता और बाइबिल और कुरान लिखने","से कोई फायदा नहीं। आप कृपया ऐसा करिए"]],[4103,["कि पहले जन-साधारण की कैसी जागृति होगी, जो","आपका कार्य है, जिसके लिए आप संसार में आईं हैं,","उसका पता लगाइये।"]],[4111,["उस वक़्त मैंने मनुष्य के अंदर की व्यवस्थाएँ देखीं,","उसकी कार्य-प्रणाली देखी, उसकी सब तरीका देखा,"]],[4118,["और फिर मैंने ये सोचा, कि क्यों न हम लोग कुछ","ऐसा तरीका निकाल सकते हैं, कि जिसके करने से ही","जन-साधारण एकदम से पार हो जाए।"]],[4126,["और ऐसी व्यवस्था बन पड़ी और मुझे एक बात समझ","में आ गई जिसकी वजह से ये कार्य नहीं हो रहा था"]],[4131,["कि सहस्त्रार टूटे बगैर मनुष्य पार नहीं हो","सकता, क्योंकि इस सहस्त्रार में सातों चक्रों","का वहाँ पर पीठ है"]],[4138,["और जब तक ये इंटीग्रेशन, ये समग्रता, हम साध","नहीं सकते, तब तक ये कार्य नहीं होगा।"]],[4144,["और जब यह कार्य सिद्ध हुआ तो मैं बड़े","आश्चर्यचकित हो गई, मैं स्वयं आश्चर्यचकित हूँ"]],[4149,["कि हज़ारों लोग एक क्षण में पार हो जाते हैं,","हज़ारों लोग, पर शहर में ज़रा मुश्किल है।"]],[4154,["शहर के लोग ज़रा इधर-उधर से ज़्यादा होशियार","होते हैं, ज़रुरत से ज़्यादा अपने को समझते हैं।"]],[4158,["जैसे आपने कहा कि हमारे अंदर ईगो आ","जाता है और बहुत सारी ऐसी चीज़ें हैं"]],[4162,["और जिनको ईगो नहीं आता, वो किसी न किसी","गलत धारणा में फँसे रहते हैं।"]],[4166,["लेकिन गाँव के सीधे-साधे लोग - महाराष्ट्र","में दस-दस हज़ार लोग एक साथ पार हो गए।"]],[4170,["दिखने में बड़ी आश्चर्यजनक चीज़ है, लेकिन ये","घटित होता है। होता है, इसमें कोई शंका नहीं।"]],[4175,["इसके लिए आप रुपया-पैसा कैसे दे सकते हैं?","परमात्मा क्या रुपया-पैसा जानते हैं? यह तो","आपने बनाई हुई चीज़ है।"]],[4182,["जो लोग आपसे रुपया-पैसा लेते हैं भगवान के नाम","पर, उस आदमी को कभी भी आप परमात्मा का","आदमी न समझें।"]],[4187,["सिर्फ जो आदमी आपको परमात्मा से मिलाए,","वही परमात्मा से आया हुआ इंसान है।"]],[4191,["क्योंकि उसको पैसे से क्या मतलब है? उसको आप","ही बताइये, कि जब आप समझ लीजिए,","कि आप तो एक बीज हैं,"]],[4198,["उसको अगर आपको चाहिए कि इसको जीवित करें","या उसमें से एक कोमल सा अंकुर निकले,"]],[4206,["तो क्या आप उसको पैसा देते हैं क्या इस मदर अर्थ","को आप पैसा देते हैं, क्या आप सूर्य को पैसा देते हैं,"]],[4212,["या जिस हवा के सहारे हम जीते हैं, इस पानी","को, इस गंगा को क्या पैसा समझ में आता है?"]],[4219,["जो पवित्र चीज़ परमात्मा की है, उसे","पैसा नहीं समझ में आता है।"]],[4222,["पहली चीज़ ये समझना चाहिए, कि जो आदमी किसी","चीज़ के लिए पैसा माँगता है और जिसे कहता है","परमात्मा, गलत चीज़ है।"]],[4228,["दूसरे यह, कि इसमें एफ्फोर्ट्लेस है, सहज है।","एफ्फोर्ट्लेसली होना चाहिए।"]],[4234,["अब कोई कहेगा, \"आप सिर के बल खड़े हो जाओ,","तुम्हारी कुण्डलिनी जागृत हो गई।\""]],[4238,["ऐसी-ऐसी किताबें लोगों ने निकाल रखीं हैं और","विशेष करके जो लोग बुद्धिवादी हैं, उनको इस तरह","की नई फैशन की किताब बड़ी अच्छी लगती है।"]],[4246,["कोई भी आ जाए नई फैशन - रजनीश आ गया,","फलाना आ गया, ढिकाना आ गया। उसका","कोई शास्त्राधार नहीं है।"]],[4251,["यह तो सारा एवोल्यूशनरी है। शास्त्र जो है","एवोल्यूशनरी है। इससे शुरुआत हुई, उससे","शुरुआत हुई, आगे ये हुआ,"]],[4257,["उसका कुछ न कुछ पाया होना चाहिए। एकदम हवा से","चीज़ निकाल के बता दी लोग मानने लग जाते हैं।"]],[4262,["जिस तरह से हमारे महाराष्ट्र में, ब्राह्मण लोगों में","बहुत बुद्धिवान हैं, उनके लिए भी उनका एक","कर्दन काल आदमी निकल आया है।"]],[4270,["उसने किताब लिखी है, उसको कहते हैं, 'करुणोपाय","अरुणोपाय करुणोपाय' मैंने कहा, \"भई ये क्या,","ये क्या है ?\""]],[4276,["कहें, \"हम उनपे शक्ति पाथ करते हैं।\" हमने","कहा, \"ये शब्द कहाँ है, शास्त्र में कहाँ है?\""]],[4283,["शक्ति पाथ, शब्द ही नहीं है। शक्ति पाथ क्या शब्द","है? कितना गन्दा शब्द है, शक्ति पाथ। ये कैसे","हो सकता है?"]],[4289,["मतलब अपना महत्व दिखाना","कि हम उसपे शक्ति पाथ करते हैं।"]],[4292,["मैंने कहा इसका कोई शास्त्र का आधार नहीं","है, ये सब आपका कर्दन काल है।"]],[4297,["और जो लोग हमारे पास आए, उनको हाई ब्लड","प्रेशर, पैरालिसिस, दुनिया भर की बीमारी।"]],[4301,["मैंने कहा, \"आपके गुरु अगर आपकी तबियत भी","नहीं ठीक कर सकते, तो उनको काहे के लिए","आप परेशान होते हैं?"]],[4307,["और वे एक साहब को लंग (फेफड़े) में कैंसर था।","मैंने उससे पूछा, \"आपके लंग का कैंसर कैसे हो गया?\""]],[4313,["उन्होंने कहा कि हमारे जो गुरु थे बड़े भगत","आदमी थे, वो किसी के हाथ का खाते नहीं थे,"]],[4318,["और हम लोगों को वो पाँचवे माले पे रहते थे और हम","लोग नीचे खाना उनके लिए गीले बदन से ऊपर ले","जाते थे रोटी"]],[4325,["और उनको देते थे। उसमें मुझे पहले निमोनिआ","हो गया। मैंने कहा, \"ठीक है, अपने गुरु के लिए"]],[4330,["तो ऐसा सैक्रिफाइस (त्याग) करना ही चाहिए।","उसके बाद अब कैंसर भी हो गया।\" मैंने कहा, \"यह भी","आप सैक्रिफाइस कर रहे हैं ?\""]],[4334,["जो गुरु आपसे सैक्रिफाइस करवाए, उसको","सोचना चाहिए गलत है। सैक्रिफाइस चीज़ बाह्य","की नहीं होती, बाह्य की नहीं होती।"]],[4341,["कि दिखाई दिया, गेरुए वस्त्र पहन लिए, मैंने ये","सैक्रिफाइस कर दिया, वो सैक्रिफाइस कर दिया।"]],[4346,["क्या सैक्रिफाइस कर रहे हैं पत्थर?","सैक्रिफाइस चीज़ अंदर की होती है।"]],[4350,["जो आदमी अंदर से छूटा हुआ है, उसको किसी चीज़","का मोह होता ही नहीं। बड़ी मुश्किल चीज़ है मोह","करना ऐसे आदमी के लिए।"]],[4356,["उसको बड़ा मुश्किल होता है कि कोई चीज़ हमें देगा।","इन चीज़ों का एक ही मुझे तो कारण दिखाई देता है कि"]],[4364,["ये चीज़ आप किसी को दे सकते हैं, इसमें","आप अपना प्यार भर सकते हैं।"]],[4368,["एक छोटी सी जैसे शबरी ने बेर राम को खिला दिए,","ऐसी ही चीज़ है, सारे संसार में सब शबरी के बेर हीं हैं।"]],[4374,["वो किसी को माँ के प्यार में हम दे दें, तो हमें","बड़ी ख़ुशी हो। चीज़ें उलटी हो जातीं हैं ना।"]],[4381,["तो ये चीज़ जब तक हमारे अंदर नहीं आएगी, तब","तक हमें मानना नहीं चाहिए कि हमने कुछ पाया है।"]],[4385,["लेकिन ऐसे भी लोग बहुत से होते हैं, कि वह कहते","हैं कि हमारी कुण्डलिनी जागरण हो गई।"]],[4389,["ऐसे भी बहुत से लोग होते हैं। कुछ तो कहते हैं,","\"इसमें बड़ी तकलीफ़ होती हैं और ऐसी-ऐसी","परेशानी होती है।\""]],[4396,["जिन लोगों का इसको अधिकार नहीं हैं, जो पवित्र","नहीं हैं, जो इसकी ओर एक गन्दी दृष्टि से देखते हैं,"]],[4401,["और जिनको इसके बारे में कुछ भी मालूमात","नहीं, वह अगर कुण्डलिनी पे आघात करें,"]],[4404,["तो ये तो श्री गणेश का हाथ है, जो मारता हैं तड़ाक से -","जिसको कि हम सिम्पैथेटिक नर्वस सिस्टम के","प्रोब्लेम्स कहते हैं, वह खड़े हो जाते हैं।"]],[4411,["और इस तरह से आदमी में अनेक तरह की विकृतियाँ","- चिल्लाना, चीखना, दुनिया भर की चीज़।"]],[4416,["एक महाशय आए, तो वह मेरी तरफ बैठे तो मेरी तरफ","उन्होंने दोनों पैर ऐसे किये, तो लोगों ने कहा,"]],[4423,["\"माँ की तरफ ऐसे पैर करके नहीं बैठते, आपको तो","पता है, आप हिंदुस्तानी हैं, आप आराम से बैठिए,\""]],[4427,["तो उन्होंने कहा कि, \"नहीं, मैं बैठ नहीं सकता,","मेरी कुण्डलिनी जागृत हो गई है।"]],[4430,["मैं अगर ऐसे बैठ जाऊँ तो पालथी मार के, तो","मैं कूदने लगता हूँ मेंढक के जैसे।\""]],[4435,["तो मैंने उसको बुलाया, \"इधर आओ, तुम क्या मेंढक","होने वाले हो? अब तुमको क्या होने का है?\""]],[4440,["तुमको तो महामानव होने का है। जिसको महामानव","होने का है, वह मेंढक के जैसे कैसे कूदेगा?"]],[4446,["इस तरह से अत्यंत विपरीत और विप्रयास किये हुए","अनेक आपको ऐसे ग्रन्थ भी मिलेंगे, जिसमें अंट- शंट","दुनिया भर की चीज़ें लिखीं।"]],[4454,["लेकिन जो कुछ सब लिखा है, शास्त्र नहीं है,","यह मानना चाहिए। जो कुछ लोग कहते हैं,","वह ब्रह्मवाक्य नहीं है।"]],[4460,["सबसे पहले आप जब तक आत्मा का अपने अंदर","जागरण नहीं करते हैं, जो कुछ आप जानते हैं,"]],[4466,["जो कुछ भी आपने पाया, कुछ भी नहीं पाया क्योंकि","सब मिथ्या है। ब्रह्म को पाए बगैर सब मिथ्या है।"]],[4473,["पहले ब्रह्म को पाइए, फिर आपको असलियत","पता हो जाएगी कि ये चीज़ क्या है?"]],[4476,["अब हम कहते हैं कि कामाख्या देवी का","मंदिर है, फलाना मंदिर है, तो क्या?"]],[4480,["ये मंदिरों में कुछ नहीं रखा क्योंकि वहाँ","सब भूत बैठ करके पैसा कमा रहे हैं।"]],[4484,["तो ज़रूरी तो ये देखिएगा किसी ने कहा कि, \"ये क्या","कामाख्या देवी का मंदिर, किसी काम का नहीं।\""]],[4489,["लेकिन ये बात नहीं। जो आदमी आत्मसाक्षात्कारी","होगा, वो देखके कहेगा, \"हाँ, ये स्वयंभू है।\""]],[4493,["ये स्वयंभू हैं, पृथ्वी तत्व से निकला हैं। अब यह बातें","सच हैं, या झूठ हैं, या कैसीं हैं, आप कैसे जानिएगा?"]],[4499,["हमारी बातचीत से तो आपको मान नहीं लेना","चाहिए। ये आप स्वयं इसकी प्रचीति लें,"]],[4504,["आप स्वयं उस चैतन्य को पाएँ और आप","खुद जा कर के देख लीजिये ये क्या चीज़ है ?"]],[4509,["इतना आप जागरूक हो जाते हैं, इतनी जागरूकता","आ जाती है, कि आप फ़ौरन समझ जाते हैं,"]],[4513,["कि आप कहाँ हैं और दूसरा कहाँ है","और उसकी क्या दशा है।"]],[4519,["दूसरी बात कि इसमें लक्ष्मी तत्व का जागृति होती है।"]],[4522,["ख़ास कर बात बताएँगे जब लक्ष्मी की जागृति हमारे","अंदर होती है तो मनुष्य का क्षेम बन जाता है।"]],[4527,["लंदन में आप जानते हैं कि कितनी","बेरोज़गारी है, बहुत ज़्यादा अनएम्प्लॉयमेंट है,"]],[4533,["लेकिन हमारे सहज योगी करीबन तीन-चार हज़ार","सहज योगी होएंगे, उसमें से एक भी बेरोज़गार नहीं है।"]],[4539,["सब के पास रोज़ी है, कोई बेरोज़गार नहीं और","सहज योग में नियम है, कि जो भी आदमी आये,","कोशिश करे रोज़गारी पा ले और रोज़गारी पा लेते हैं।"]],[4548,["इतनी तरह-तरह से परमात्मा की","हमें मदद होती है।"]],[4551,["उसकी वजह ये है कि, जिसे हम कहते हैं कारण","और परिणाम, कॉज एंड इफ़ेक्ट, उससे परे","आप चले जाते हैं।"]],[4557,["कुण्डलिनी जो है, वह उससे परे है। उस परमात्मा","के साम्राज्य में आप चले जाते हैं, जो कॉज एंड","इफ़ेक्ट के बाहर है।"]],[4566,["हम लोग तो लड़ते रहते हैं कारण से या उसके परिणाम","से। जैसे अब गरीबी है, गरीबी की वजह से खराब है।"]],[4572,["तो गरीबी से परे उठने का तरीका सिर्फ","कुण्डलिनी जागरण है - सच बात है।"]],[4577,["जब तक आपके यहाँ ये तांत्रिक बने रहेंगे इस बंगाल","में, कभी भी यहाँ लक्ष्मी का राज्य नहीं आ सकता।"]],[4582,["आपको मालूम नहीं इधर से तांत्रिक आया और उधर","से लक्ष्मी जी चलीं गईं। इतने तांत्रिक भरे हुए हैं","इस बंगाल में, कि यहाँ कैसे होगा।"]],[4590,["वही हाल मैंने केरला में देखा था, कि केरला में","लोग घर में ही मुर्दे गाड़ते हैं और इतनी काली","विद्या वहाँ करते हैं।"]],[4596,["जहाँ-जहाँ काली विद्या होएगी - आप देश के कहीं कोने","में चले जाइये जहाँ काली विद्या होएगी, वहाँ कभी भी","लक्ष्मी जी का राज्य नहीं होगा।"]],[4604,["इसीलिए हम, आप जानते हैं, कि जिस दिन दिवाली","होती है, तो सब दूर लाइट जला देते हैं, जिससे","लक्ष्मी जी अंदर बनीं रहें।"]],[4611,["उनको बिलकुल पसंद नहीं कि हम ऐसे काले लोगों के","पास जाएँ, पर इसका यहाँ इतना ज़ोर बंधा हुआ है"]],[4616,["और गलत गुरु इतने ज़्यादा हैं कि मैं बहुत यहाँ आने","से डरती थी। आपको मालूम है मैंने करीबन चौदह","साल से सहज योग हिंदुस्तान में शुरू किया"]],[4624,["लेकिन आज इतने दिनों के बाद आने की वजह यह थी,","कि मैंने सोचा कि यहाँ पाँव कहीं धरने की जगह","मिले, तो फिर ज़रूर आयें।"]],[4631,["मुझे आशा है कि आप लोग इस ओर अपनी","दृष्टि करेंगे, क्योंकि आप स्वच्छ, शुद्ध,","शाश्वत, अविनाशी आत्मा हैं।"]],[4641,["उस आत्मा को पाना, ये आपका, स्वयं का जन्म सिद्ध","अधिकार है। उसके लिए हम कुछ नहीं कर रहे हैं।"]],[4648,["ये आपके पास है, तैयारी है, आपको सिर्फ","प्राप्त करना है। लेकिन उस वक़्त अपना दिमाग","खुला रखना चाहिए।"]],[4655,["अगर आप साइंटिस्ट हैं, तो साइंटिस्ट चाहता","है कि मैं अपना दिमाग खुला रखूँ।"]],[4659,["उस दिमाग को खुला रख करके आपको सोचना","चाहिए, कि जो माँ कह रही है यह बात है या नहीं।"]],[4665,["जैसे कि जिसे हाइपोथिसिस कहते हैं, धारणा","कहते हैं, उस तरह से आप मेरी बात सुनिए।"]],[4670,["उसके बाद वह सिद्ध होने पर आपको मानना चाहिए।","पर शुरू से ही आप 'नाहीं नाहीं' करने लग जाएँ","तो चीज़ कैसे अंदर जाएगी ?"]],[4676,["हाँलाँकि इसका बुद्धि से कोई सम्बन्ध नहीं होता है।"]],[4678,["ऐसे भी लोग मैंने देखे हैं कि जिन्होंने","बहुत ओप्पोसिशन(विरोध) सहज योग को किया।"]],[4682,["खुद हमारे जो डॉक्टर वारेन हैं, इन्होंने बहुत","शुरू में परेशानी उठाई थी लेकिन आज देखिये,","कहाँ से कहाँ पहुँच गए हैं, कहाँ से कहाँ पहुँच गए हैं ।"]],[4689,["क्योंकि ये अनुभव है। अनुभव को भी अगर आप कहें,","\"हाँ, तो क्या, हमारे हाथ में ठंडी हवा आ गई तो क्या?\""]],[4695,["सिर्फ सहजयोग का जो सबसे बड़ा दोष ये है, कि","सहजयोग के लिए हर आदमी खुला है। हर तरह का","आदमी इसमें आता है।"]],[4702,["इसके लिए सबके लिए दरवाज़े खुले हैं। हो सकता","है, इसमें एक-आद दो गलत आदमी भी आ जाएँ।"]],[4707,["एक-आद दो ढोंगी भी आ जाएँ, एक-दो","बनाने वाले भी आ जाएँ।"]],[4710,["लेकिन जब आपकी जाग्रति होकर के ये अवस्था","आ जाएगी, आप फ़ौरन ताड़ जाईयेगा कि","ये आदमी कैसा है, इसके विब्रेशन्स कैसे हैं।"]],[4717,["लेकिन ये जब तक आपके अंदर उत्थान होता नहीं,","उत्क्रांति होती नहीं, आप अधूरे रह गए,"]],[4722,["आप मनुष्य ही की दशा में रह गए। जिस लिए आपको","मनुष्य बनाया था, वह चीज़ आपने पाई ही नहीं-","वह है आत्मा को पाना।"]],[4729,["और फिर कहना चाहिए कि हमारा ये धरोहर है, ये","हमारा हेरिटेज है। ये हमारे भारतवर्ष का हेरिटेज है।"]],[4736,["ये किसी के पास नहीं। ये जो बाहर के देशों ने जितनी","भी आपने देखी है कि बड़ी डेवलपमेंट हो गई और ये"]],[4742,["ये सिर्फ, पेड़ जैसा बढ़ जाए बगैर किसी जड़ों के","और एक दिन उलट के गिर जाए,"]],[4747,["और अभी उनके दिमाग ठनके हुए हैं सबके और","सोचते हैं कि हम किसी तरह से विनाश की ओर","दौड़े चले जाएँ,"]],[4754,["क्योंकि आपने अपनी जड़ें नहीं खोजीं और जड़ इस","देश में है और हम लोग उनके चरण छू रहे हैं,","तो क्या होगा ?"]],[4759,["जब जड़ें इस देश में हैं तो आपको पाना चाहिए।"]],[4762,["वहाँ तो गणपति का 'ग' से उन्हें शुरू करना पड़ता है,","धार्मिकता से शुरू करना पड़ता है। मेरे हाथ टूट जाते","हैं लोगों को वहाँ पार कराते-कराते।"]]]);
